INSERT INTO public.preguntas
  ("año", numero, especialidad, pregunta, opcion_a, opcion_b, opcion_c, opcion_d, opcion_e, correcta, imagen_path, tema)
VALUES
  (2024, 1, NULL, 'En un programa de reforzamiento observamos un patrón que se caracteriza por una alta tasa de respuestas y una pausa después de cada reforzamiento. ¿Qué tipo de programa es?:', 'Intervalo fijo.', 'Intervalo variable.', 'Razón fija.', 'Razón variable.', NULL, 'c', NULL, NULL),
  (2024, 2, NULL, 'El proceso cognitivo para la solución de problemas puede verse interferido por una tendencia a asignar una función fija a algo que hemos aprendido a usar de una manera particular. Por ejemplo, se limita el uso de un objeto a su uso tradicional. ¿Cómo se denomina esta tendencia?:', 'Fijación funcional.', 'Efecto de anclaje.', 'Sesgo de utilidad.', 'Sesgo de disponibilidad.', NULL, 'a', NULL, NULL),
  (2024, 3, NULL, 'La teoría de la emoción de Cannon-Bard postula que:', 'Los estímulos del ambiente causan cambios fisiológicos en nuestro cuerpo que interpretamos como emociones.', 'Los cambios fisiológicos específicos causan emociones específicas.', 'Las emociones y las respuestas corporales ocurren al mismo tiempo, no una después de la otra.', 'La situación en la que estamos nos brinda señales que nos ayudan a interpretar ese estado general de activación.', NULL, 'c', NULL, NULL),
  (2024, 4, NULL, '¿Cómo se denomina a la tendencia de los adolescentes a sentir que son constantemente observados por los demás y que la gente siempre está juzgando su apariencia y su conducta?:', 'Fábula personal.', 'Audiencia imaginaria.', 'Identidad difusa.', 'Confusión de roles.', NULL, 'b', NULL, NULL),
  (2024, 6, NULL, 'En las tareas de búsqueda visual, determinados estímulos como los animales desagradables (serpientes, arañas, etc.) se descubren antes que otro tipo de estímulos de contenido neutral. ¿Cómo se denomina este fenómeno?:', 'Pop out o saliencia atencional.', 'Top-down o procesamiento rápido.', 'Fear o percepción de peligro.', 'Stroop o procesamiento simultáneo.', NULL, 'a', NULL, NULL),
  (2024, 7, NULL, 'Según la teoría de detección de señales (Green y Swets, 1966), ¿qué determina que una persona detecte un estímulo?:', 'La intensidad del estímulo y su naturaleza.', 'La sensibilidad del observador y su criterio de respuesta.', 'La sensibilidad del entorno y las condiciones naturales.', 'La intensidad del estímulo y el lugar en el que ocurre.', NULL, 'b', NULL, NULL),
  (2024, 8, NULL, 'Es sencillo responder a la pregunta “¿Qué tal el desayuno de esta mañana?”. Sin embargo, cuando preguntamos “¿Qué tal el desayuno de hace una semana?”, la respuesta se complica. ¿Cómo se denomina esta dificultad para acceder a la información según las teorías de la interferencia?:', 'Interferencia constructiva.', 'Interferencia por usar partes de un conjunto como clave (part-set cuing inhibition).', 'Interferencia por sobrecarga de las claves.', 'Olvido.', NULL, 'c', NULL, NULL),
  (2024, 9, NULL, '¿Cuál de las siguientes alternativas constituye una actuación de riesgo para la mala praxis en psicoterapia?:', 'Realizar anotaciones subjetivas en la historia clínica.', 'La derivación de pacientes desde instituciones públicas a privadas.', 'Solicitar consentimiento informado a pacientes con trastorno mental grave estabilizados clínicamente.', 'Revelar información clínica a petición de una instancia judicial.', NULL, 'b', NULL, NULL),
  (2024, 10, NULL, 'Con respecto a las relaciones duales en psicoterapia:', 'El profesional que incurre en ellas mantiene límites profesionales rígidos en el transcurso de la psicoterapia.', 'Existe consenso en considerar a los negocios con pacientes como la variante más inapropiada de relación dual.', 'Pueden darse al mismo tiempo que ocurre la intervención psicoterapéutica o después de la misma.', 'Las relaciones duales de tipo sexual quedan excluidas de la definición.', NULL, 'c', NULL, NULL),
  (2024, 11, NULL, 'Gema y Vanesa llevan un año en tratamiento por cáncer de mama y en el momento actual presentan sintomatología ansioso-depresiva, miedo a que el cáncer recidive, a no poder ser madres, no poder volver a trabajar y sienten una gran insatisfacción con su imagen corporal. La oncóloga de Gema le ha propuesto ser derivada al Servicio de Psicología Clínica del mismo hospital, mientras que la oncóloga de Vanesa le ha recomendado buscar ayuda psicológica a nivel privado o en una ONG. ¿Qué principio bioético se está poniendo en riesgo en esta situación?:', 'Principio de justicia o equidad.', 'Principio de beneficencia.', 'Principio de solidaridad.', 'Principio de igualdad.', NULL, 'a', NULL, NULL),
  (2024, 12, NULL, 'El fenómeno sanitario caracterizado por una mayor accesibilidad a cuidados por parte de aquellos que menos lo necesitan, en detrimento de quienes más lo necesitan, se denomina:', 'Ley de cuidados no escalados.', 'Ley de cuidados inversos.', 'Ley de la desigualdad de los cuidados.', 'Ley de la desigualdad estructural.', NULL, 'b', NULL, NULL),
  (2024, 13, NULL, '¿Qué técnica de escucha activa (directiva) ayuda a comprender los objetivos del tratamiento y a cambiar la forma de interpretar la conducta de otra persona o situación para que responda de modo diferente?:', 'Indagación o sondeo.', 'Encuadre.', 'Confrontación.', 'Instrucciones.', NULL, 'b', NULL, NULL),
  (2024, 14, NULL, 'El Inventario de Trastornos de la Conducta Alimentaria EDI-3:', 'Está diseñado para mayores de 16 años.', 'Sus autores son Cooper, Taylor y Fairburn.', 'Tiene tres escalas de riesgo de trastorno de la conducta alimentaria: obsesión por la delgadez, bulimia e insatisfacción corporal.', 'Sólo puede utilizarse en población clínica.', NULL, 'c', NULL, NULL),
  (2024, 15, NULL, 'De acuerdo con la Escala de Observación para el Diagnóstico del Autismo-2 (ADOS-2), ¿qué módulo se aplica a niños y adolescentes con lenguaje fluido que aún se encuentran en la edad de jugar con juguetes?:', 'Módulo 1.', 'Módulo 2.', 'Módulo 3.', 'Módulo T.', NULL, 'c', NULL, NULL),
  (2024, 16, NULL, 'La Entrevista Diagnóstica para Pacientes Límite-Revisada (DIB-R; Zanarini et al., 1989), utilizada para la evaluación del trastorno límite de la personalidad, está compuesta por cuatro escalas o áreas generales. ¿Cuál de las siguientes opciones NO forma parte de esta entrevista?:', 'Inestabilidad.', 'Impulsividad.', 'Afecto.', 'Relaciones interpersonales.', NULL, 'a', NULL, NULL),
  (2024, 17, NULL, 'En relación con los métodos de evaluación utilizados en el trastorno bipolar (TB):', 'La escala de Young para la manía (YMRS) resulta apropiada también para valorar TB tipo II.', 'El registro gráfico de la intensidad de los síntomas durante un periodo de tiempo considerable permite desarrollar un gráfico vital que puede servir para mejorar la conciencia del problema por parte del paciente.', 'La lista de valoración de hipomanía (HCL-32) resulta útil para el diagnóstico de TB tipo I.', 'En general, el diagnóstico de fases maníacas es sencillo, puesto que el paciente suele identificar claramente los síntomas como problema.', NULL, 'b', NULL, NULL),
  (2024, 18, NULL, 'Cuando una persona obtiene una puntuación directa de 0 en una de las escalas del WAIS-IV, ¿qué podemos concluir?:', 'Refleja que la aptitud del sujeto no puede determinarse por el conjunto de ítems de la prueba.', 'No es posible obtener una puntuación directa de 0, ya que el rango de posibles puntuaciones va de 1 a 19.', 'Si la puntuación directa de 0 se produce en Vocabulario no se puede calcular el Índice de Comprensión Verbal.', 'Es obligatorio sustituir el Índice de CI total por el Índice de Capacidad General.', NULL, 'a', NULL, NULL),
  (2024, 19, NULL, '¿Cuál de las siguientes pruebas sería válida para valorar praxias constructivas y, en caso de existir, podría detectar fenómenos como la heminegligencia?:', 'Test del reloj.', 'Test de fichas (Token test).', 'Test conductual de memoria de Rivermead (RBMT).', 'Paced Auditory Serial Addition Test (PASAT).', NULL, 'a', NULL, NULL),
  (2024, 20, NULL, 'El estilo personal del terapeuta es un constructo que se puede evaluar mediante el Cuestionario de Evaluación del Estilo Personal del Terapeuta (EPT-C). En este sentido, el EPT-C es un instrumento de medida que:', 'Cuenta con una dilatada trayectoria de investigación psicométrica, incluida una validación y estandarización en inglés.', 'Cuenta con una dilatada trayectoria de investigación psicométrica, pero sólo incluye validaciones y estandarizaciones en Latinoamérica.', 'Cuenta con diferentes validaciones y estandarizaciones que confluyen en una solución pentafactorial en todos los casos.', 'Cuenta con una dilatada trayectoria de investigación psicométrica, incluida una validación en España que presenta una solución pentafactorial compuesta por 20 ítems.', NULL, 'd', NULL, NULL),
  (2024, 21, NULL, 'En relación con las listas de rasgos o registros observacionales de conductas:', 'Constituyen un listado de diferentes conductas que pertenecen a múltiples dimensiones y son mutuamente excluyentes entre sí.', 'Disponemos de tres tipos: Catálogos, Repertorios y Matrices de Interacción.', 'Los Catálogos son listas siempre abiertas que se usan para la construcción de formatos de campo.', 'Los Repertorios tienen garantía de exhaustividad.', NULL, 'c', NULL, NULL),
  (2024, 22, NULL, 'Según la CIE-11, señale la alternativa FALSA sobre la escala “Adjustment Disorder-New Module” (ADNM) que evalúa el trastorno de adaptación:', 'Tiene dos formatos: la entrevista clínica estructurada y el cuestionario de autoinforme.', 'Evalúa los acontecimientos vitales estresantes que han ocurrido en los 3 años anteriores.', 'Se evalúan los síntomas centrales del trastorno adaptativo y la posible sintomatología asociada (estado de ánimo deprimido, ansiedad, evitación, problemas de control de impulsos).', 'Evalúa el nivel de deterioro en distintas áreas de funcionamiento.', NULL, 'b', NULL, NULL),
  (2024, 23, NULL, 'Señale cuál de los siguientes instrumentos de evaluación de las alucinaciones NO es un autoinforme:', 'Psychotic Symptom Rating Scale (PSY-RATS; Haddock et al., 1999; González et al., 2003).', 'Launay-Slade Hallucination Scale-revised (LSHS-R; Bentall y Slade, 1985; Fonseca Pedrero et al., 2010).', 'Voice Power Differential Scale (VPDS; Birchwood et al., 2000).', 'Beliefs About Voices Questionnaire (BAVQ-R; Chadwick et al., 2000; Robles García et al., 2004).', NULL, 'a', NULL, NULL),
  (2024, 24, NULL, 'Con respecto a la formulación del caso en la terapia cognitiva (Clark y Beck, 2012):', 'Persons y sus colaboradores (Persons, 1989; Persons y Davidson, 2001) elaboraron uno de los modelos más comprensivos, subrayando su naturaleza individualizada, dirigida por la práctica y generadora de hipótesis.', 'Persons y sus colaboradores (Persons, 1989; Persons y Davidson, 2001) elaboraron uno de los modelos más comprensivos, subrayando su naturaleza transdiagnóstica, dirigida por la teoría y generadora de hipótesis.', 'A menudo, el fracaso de un tratamiento con casos difíciles puede atribuirse a una conceptualización incompleta.', 'Es fundamental que se dirija sin influencias teóricas.', NULL, 'c', NULL, NULL),
  (2024, 25, NULL, 'En relación con las técnicas de escucha activa no directivas, ¿cuál tiene como objetivo ayudar a la autoexploración del entrevistado suponiendo que es frecuente que se relacione con el clínico del mismo modo?:', 'Interpretación.', 'Inmediatez.', 'Autorrevelación.', 'Afirmación de la capacidad.', NULL, 'b', NULL, NULL),
  (2024, 26, NULL, '¿Cuál de los siguientes instrumentos permite evaluar la percepción social en niños?:', 'Escala de Aptitudes Intelectuales, BAS-II.', 'Batería de Diagnóstico Neuropsicológico Infantil de Luria, DNI.', 'Escala de Inteligencia no verbal Leiter-R.', 'Batería Neuropsicológica Infantil, NEPSY-II.', NULL, 'd', NULL, NULL),
  (2024, 27, NULL, 'En relación con la evaluación psicológica mediante las escalas WISC-V:', 'El CI Total se obtiene tomando las puntuaciones escalares de 10 subescalas.', 'Una puntuación en comprensión verbal significativamente mayor que la de memoria de trabajo permite confirmar el diagnóstico de trastorno por déficit de atención.', 'Una puntuación por debajo de 70 en la escala de CI Total nos indica que existe una discapacidad intelectual.', 'Una diferencia significativa entre el índice de competencia cognitiva y el índice de capacidad cognitiva orienta hacia dificultades atencionales.', NULL, 'd', NULL, NULL),
  (2024, 28, NULL, '¿Cuál de los siguientes instrumentos puede utilizarse para valorar el nivel madurativo de un menor?:', 'Test del dibujo de dos figuras humanas (T2F).', 'The Story Stem Assessment Profile (SSAP).', 'The Children’s Global Assessment Scale (CGAS).', 'Cuestionario de fortalezas y dificultades (SDQ).', NULL, 'a', NULL, NULL),
  (2024, 29, NULL, '¿Cuál de los siguientes factores debemos valorar de manera específica en un caso de trastorno obsesivo compulsivo en la infancia y la adolescencia?:', 'La acomodación familiar.', 'Los antecedentes de tratamiento en salud mental de los padres.', 'El nivel de rendimiento académico.', 'Las dificultades para la interacción social.', NULL, 'a', NULL, NULL),
  (2024, 30, NULL, '¿Cuál de los siguientes instrumentos está indicado para evaluar estados de alto riesgo de psicosis?:', 'PANSS (Positive and Negative Syndrome Scale for Schizophrenia).', 'SIPS (Structured Interview for Prodromal Syndromes).', 'K-SADS-PL (Kiddie Schedule for Affective Disorders and Schizophrenia, Present and Lifetime version).', 'BSABS (Bonn Scale for the Assessment of Basic Symptoms).', NULL, 'b', NULL, NULL),
  (2024, 31, NULL, 'Uno de los índices de aptitud intelectual que evalúa el BAS-II es el Índice Verbal. ¿Con qué pruebas se calcula este índice?:', 'Copia y cubos.', 'Comprensión verbal y nominación.', 'Conceptos numéricos y comprensión verbal.', 'Semejanzas y fluidez verbal.', NULL, 'b', NULL, NULL),
  (2024, 32, NULL, '¿Cuál de las siguientes conductas se corresponde con una manifestación temprana de alerta para detectar el TEA entre los 12 y los 18 meses de edad?:', 'Inversión pronominal.', 'Regresión o pérdida de habilidades comunicativas.', 'Dificultad para comprender las normas sociales.', 'Dificultad para comprender dobles sentidos.', NULL, 'b', NULL, NULL),
  (2024, 33, NULL, 'En relación con el Inventario de Evaluación de la Personalidad para Adolescentes (PAI-A):', 'Su autor es Butcher.', 'Contiene cinco escalas de consideraciones para el tratamiento: agresión, ideaciones suicidas, estrés, falta de apoyo social y rechazo al tratamiento.', 'Está diseñado para la evaluación de la personalidad y la psicopatología en adolescentes, con edades comprendidas entre los 14 y los 18 años.', 'Contiene dos escalas de relaciones interpersonales: Dominancia y Extraversión.', NULL, 'b', NULL, NULL),
  (2024, 34, NULL, 'La Entrevista Estructurada para la Organización de la Personalidad-Revisada (STIPO-R) evalúa cinco dimensiones o ámbitos de contenido. ¿Cuál de las siguientes opciones NO es evaluada por este instrumento?:', 'Inestabilidad afectiva.', 'Identidad.', 'Agresión.', 'Valores morales.', NULL, 'a', NULL, NULL),
  (2024, 35, NULL, 'Según la Children’s Global Assessment Scale (CGAS), ¿en qué rango de puntuación situaríamos a un menor en el que queremos reflejar un deterioro importante en el funcionamiento de varias áreas?:', '81-90.', '61-70.', '31-40.', '11-20.', NULL, 'c', NULL, NULL),
  (2024, 36, NULL, '¿Cuál de los siguientes conceptos NO se considera una de las principales manifestaciones del egocentrismo intelectual en el periodo preoperatorio?:', 'Finalismo.', 'Realismo.', 'Conservación.', 'Animismo.', NULL, 'c', NULL, NULL),
  (2024, 37, NULL, 'Según la investigación, ¿a qué edad se resuelve con seguridad la tarea de la “Falsa Creencia”?:', '4-5 años.', '2-3 años.', '6-7 años.', '10-12 años.', NULL, 'a', NULL, NULL),
  (2024, 38, NULL, 'Señale cuál de las siguientes opciones hace referencia a la función de adaptación descrita por Piaget:', 'Es la forma en la que los niños manejan la nueva información sobre el entorno en base a lo que ya saben del mundo.', 'Es el proceso por el cual se recibe nueva información y se incorpora a las estructuras cognoscitivas previas.', 'Consiste en ajustar las estructuras cognoscitivas previas para que acepten la nueva información.', 'Permite gobernar la forma en la que los niños piensan y se conducen en una situación particular.', NULL, 'a', NULL, NULL),
  (2024, 39, NULL, 'Dentro de las teorías del desarrollo humano, señale la que plantea que los seres humanos poseen mecanismos de adaptación para sobrevivir que interactúan con el ambiente existente para determinar el comportamiento:', 'Teorías cognoscitivas.', 'Teorías sociobiológicas.', 'Teorías contextuales.', 'Teorías del aprendizaje.', NULL, 'b', NULL, NULL),
  (2024, 40, NULL, '¿Cuál de las siguientes habilidades se desarrolla durante el período sensoriomotor?:', 'La noción de número.', 'La correlación.', 'La inferencia.', 'El descentramiento.', NULL, 'a', NULL, NULL),
  (2024, 41, NULL, '¿Qué teoría afirma que el menor organiza la información acerca de lo que se considera apropiado para cada género en base a lo que dicta una cultura particular y se autocategoriza en función del procesamiento de la información cultural?:', 'Teoría del desarrollo cognoscitivo.', 'Teoría psicosexual.', 'Teoría de los esquemas de género.', 'Teoría cognoscitiva social.', NULL, 'c', NULL, NULL),
  (2024, 42, NULL, 'La teoría de la ampliación-construcción de las emociones positivas de Fredrickson plantea que:', 'A pesar de sus efectos beneficiosos, las emociones positivas son peligrosas al disminuir la flexibilidad de los procesos cognitivos.', 'Las emociones positivas están implicadas en el proceso de adaptación psicológica que favorece la supervivencia humana.', 'A pesar de sus efectos beneficiosos, las emociones positivas son poco adaptativas al producir el acomodamiento, disminuir la creatividad y la resistencia a la adversidad.', 'Las emociones positivas son adaptativas porque disminuyen el foco atencional y lo centran en una única respuesta.', NULL, 'b', NULL, NULL),
  (2024, 43, NULL, 'En los estudios longitudinales sobre la estabilidad de la personalidad realizados con el California Psychological Inventory (CPI) se ha observado que:', 'Las personas mayores, en comparación con sus evaluaciones realizadas cuando eran más jóvenes, tienden a puntuar más en autocontrol, responsabilidad y cooperación.', 'La afabilidad y el tesón disminuyen con la edad.', 'La vitalidad social aumenta con la edad mientras que la dominacia social disminuye.', 'La estabilidad emocional aumenta ligeramente hasta la edad adulta (aproximadamente 40 años) y entonces desciende drásticamente.', NULL, 'a', NULL, NULL),
  (2024, 44, NULL, 'Mischel y Shoda (1995) proponen reglas o unidades específicas para la interacción entre la situación y la conducta. Estas reglas siguen el esquema:', 'Si es A, puede ser X.', 'Evaluar A, actuar X.', 'Debería A, no debería X.', 'Si A, entonces X.', NULL, 'd', NULL, NULL),
  (2024, 45, NULL, 'Uno de los avances metodológicos que ha contribuido al estudio de la Psicología Diferencial fue el desarrollo del Análisis Factorial Confirmatorio, que presenta un mayor potencial explicativo que técnicas previas. ¿Qué autores lo desarrollaron?:', 'Jöreskog y Sörbom.', 'Kaiser y Carroll.', 'Nesselroade y Cattell.', 'Kline y Tyler.', NULL, 'a', NULL, NULL),
  (2024, 46, NULL, 'Basándose en la tradición del análisis lexicográfico de Allport y Odbert, Cattell describió una fuente de datos que se basaba en descripciones u observaciones externas al propio individuo. Esta fuente de datos son los:', 'Datos L o Life.', 'Datos D o Dictionary.', 'Datos Q o Questionnaire.', 'Datos T o Test.', NULL, 'a', NULL, NULL),
  (2024, 47, NULL, 'Según la teoría triárquica de la inteligencia de Sternberg:', 'Los individuos que se caracterizan por una inteligencia analítica tienen mayor habilidad para adaptarse, modelar y seleccionar aquellos entornos más apropiados.', 'Los individuos que se caracterizan por una inteligencia creativa tienen mayor habilidad para aplicar componentes de creación y descubrimiento.', 'Los individuos que se caracterizan por una inteligencia práctica tienen mayor habilidad para el manejo óptimo de los componentes internos (metacomponentes, componentes de adquisición y de ejecución).', 'Los individuos que se caracterizan por una inteligencia naturalista tienen mayor habilidad para identificar y caracterizar objetos naturales (animales, insectos, hierbas, etc.).', NULL, 'b', NULL, NULL),
  (2024, 48, NULL, '¿Cuáles son las tres funciones importantes del intelecto propuestas por Binet y Simon en 1916?:', 'Habilidad, adaptación y control.', 'Capacidad, adaptación y control.', 'Dirección, adaptación y control.', 'Dirección, adaptación y habilidad.', NULL, 'c', NULL, NULL),
  (2024, 49, NULL, 'En relación con el estudio de las influencias culturales en la personalidad:', 'Las sociedades colectivistas muestran mayor motivación de aproximación.', 'Las sociedades individualistas se orientan más a la evitación del fracaso.', 'En las sociedades colectivistas es natural que las personas atiendan selectivamente a los atributos negativos en forma de autocrítica.', 'Las personas de sociedades colectivistas muestran un estilo atribucional defensivo para mantener su autoestima.', NULL, 'c', NULL, NULL),
  (2024, 50, NULL, 'Según la Teoría de la Autodeterminación (Decy y Ryan, 2008; 2009), ¿en qué nivel del proceso de internalización se encontraría una persona que estudia para evitar la culpa derivada de disgustar a sus padres?:', 'Regulación externa.', 'Regulación introyectada.', 'Regulación identificada.', 'Regulación integrada.', NULL, 'b', NULL, NULL),
  (2024, 51, NULL, '¿Qué fenómeno explica la paradoja de Easterlin (2001) descrita en los estudios sobre la relación entre el estatus económico y el bienestar subjetivo?:', 'Explica que a medida que aumenta la renta personal disponible, cada dólar adicional contribuye más al bienestar subjetivo.', 'Describe que existe un efecto lineal en la correlación entre los ingresos económicos de las personas y su bienestar subjetivo.', 'Describe que las correlaciones más altas entre el estatus económico y el bienestar subjetivo se obtienen en países con alto nivel de desarrollo económico.', 'Explica que en las personas que tienen solucionadas las necesidades básicas, es el estatus económico relativo lo que incide en su percepción de bienestar subjetivo.', NULL, 'd', NULL, NULL),
  (2024, 52, NULL, '¿A qué hace referencia la subescala de planificación estratégica del Cuestionario de Afrontamiento Proactivo (Greenglass, 2002; Greenglass, Schwarzer y Taubert, 2000)?:', 'Al planteamiento autónomo de objetivos, así como a los pensamientos y conductas que facilitan el logro de dichos objetivos.', 'Al establecimiento de prioridades y la habilidad para dividir las tareas en componentes más asequibles.', 'A la capacidad para contemplar y diseñar mentalmente planes alternativos de actuación.', 'A la capacidad para anticipar y prepararse ante potenciales estresores.', NULL, 'b', NULL, NULL),
  (2024, 53, NULL, 'Señale cuál de los siguientes NO es un factor de orden superior de la personalidad según el Modelo Dimensional de W. J. Livesley:', 'Desregulación emocional.', 'Comportamiento antisocial.', 'Extraversión.', 'Compulsividad.', NULL, 'c', NULL, NULL),
  (2024, 54, NULL, 'Los estudios de metaanálisis de Feingold (1994) sobre las diferencias individuales en personalidad entre hombres y mujeres señalan que:', 'Las mujeres presentan mayores niveles de ansiedad e impulsividad que los hombres.', 'Las mujeres puntuaron significativamente más alto en asertividad.', 'Los hombres obtuvieron puntuaciones significativamente más elevadas en confianza y sensibilidad.', 'Aunque las mujeres puntuaron ligeramente por encima de los hombres en organización (orden, rectitud, escrupulosidad) no se encontraron diferencias significativas de género.', NULL, 'd', NULL, NULL),
  (2024, 55, NULL, 'Según la Teoría Componencial de R. Sternberg sobre el procesamiento de la información, ¿a qué tipo de componente pertenecen la codificación de la naturaleza del estímulo, la inferencia de relaciones entre estímulos y la aplicación de la inferencia previa a nuevas situaciones?:', 'Metacomponentes.', 'Componentes de ejecución.', 'Componentes de adquisición del conocimiento.', 'Componentes de planificación global.', NULL, 'b', NULL, NULL),
  (2024, 56, NULL, 'En relación con las diferencias entre estilos y controles cognitivos descritas por Allport:', 'Los estilos cognitivos son entidades de naturaleza psicodinámica.', 'Los estilos cognitivos son más generales y varían menos en función del contenido de las tareas.', 'Los controles cognitivos son bipolares.', 'Los controles cognitivos consisten en la organización de las dimensiones (etiquetas) específicas dentro del individuo.', NULL, 'b', NULL, NULL),
  (2024, 57, NULL, 'El crecimiento del cerebro en la infancia y la adolescencia se caracteriza por lo siguiente:', 'Las distintas zonas cerebrales se mielinizan a la vez, y el ritmo de maduración y formación de conexiones es estable a lo largo del desarrollo.', 'Las distintas zonas cerebrales se mielinizan a la vez, y el ritmo de maduración y formación de conexiones es en forma de brotes de crecimiento.', 'Las distintas zonas cerebrales se mielinizan a distinto ritmo (unas zonas antes que otras), y el ritmo de maduración y formación de conexiones es estable a lo largo del desarrollo.', 'Las distintas zonas cerebrales se mielinizan a distinto ritmo (unas zonas antes que otras), y el ritmo de maduración y formación de conexiones es en forma de brotes de crecimiento.', NULL, 'd', NULL, NULL),
  (2024, 58, NULL, '¿Qué estructura cerebral suele estar afectada si aparecen problemas en la memoria prospectiva en un paciente con lesiones cerebrales?:', 'El córtex temporal inferior.', 'El córtex prefrontal.', 'El hipocampo y zonas parahipocampales.', 'El hipotálamo.', NULL, 'b', NULL, NULL),
  (2024, 59, NULL, 'Si un niño sufre una lesión grave en el hemisferio izquierdo y pierde la capacidad lingüística, ¿puede el cerebro “mover” la función del lenguaje al hemisferio derecho?:', 'No hay casos documentados de este tipo de transferencia de función, incluso a pesar de la rehabilitación neuropsicológica, logopédica o cualquier otra técnica.', 'No sucede de modo natural, pero se ha conseguido artificialmente mediante estimulación magnética transcraneal.', 'Puede suceder, pero sólo si la lesión se da en momentos tempranos del neurodesarrollo.', 'Puede suceder y se da hasta el fin del neurodesarrollo (20-25 años de edad).', NULL, 'c', NULL, NULL),
  (2024, 60, NULL, 'Según el modelo de reserva cognitiva de Yaakov Stern y su relación con el diagnóstico de Enfermedad de Alzheimer, las personas con alta reserva cognitiva:', 'Tienen un diagnóstico de Alzheimer posterior en el tiempo, con respecto a las personas con baja reserva cognitiva, y además la progresión es más lenta.', 'Tienen un diagnóstico de Alzheimer posterior en el tiempo, con respecto a las personas con baja reserva cognitiva, pero la progresión es más rápida.', 'Reciben el diagnóstico de Alzheimer en un momento similar, con respecto a las personas con baja reserva cognitiva, pero la progresión es más lenta.', 'No ha podido vincularse la reserva cognitiva con la evolución y pronóstico en la Enfermedad de Alzheimer, sino únicamente con diagnósticos de deterioro cognitivo leve y alteraciones de memoria asociadas a la edad.', NULL, 'b', NULL, NULL),
  (2024, 61, NULL, '¿Cuál de los siguientes síntomas o signos motores es propio de una lesión cerebelosa?:', 'Movimientos coreicos.', 'Hemibalismo.', 'Temblor intencional.', 'Atetosis.', NULL, 'c', NULL, NULL),
  (2024, 62, NULL, 'En el procesamiento auditivo humano:', 'El área auditiva primaria está situada en el extremo inferior de la circunvolución poscentral.', 'Las fibras de proyección principales hacia el área auditiva primaria surgen del núcleo geniculado lateral.', 'Una lesión unilateral del área auditiva produce sordera completa en ambos oídos.', 'El área sensitiva del lenguaje o área de Wernicke está localizada en la circunvolución temporal superior en el hemisferio dominante.', NULL, 'd', NULL, NULL),
  (2024, 63, NULL, 'El modelo pasivo de reserva cognitiva cerebral:', 'Se relaciona con el potencial anatómico del cerebro de la persona.', 'Se cree que prolonga o incluso revierte, en ciertos casos, el estado clínico en las demencias diagnosticadas.', 'Refleja una habilidad individual para utilizar procesos cognitivos y redes neuronales de modo eficiente, disminuyendo el impacto del envejecimiento.', 'Incluye factores como el nivel educativo previo, la ocupación y los hábitos de vida y salud, pero no estima la influencia del cociente intelectual premórbido de la persona.', NULL, 'a', NULL, NULL),
  (2024, 64, NULL, '¿Cuál de los siguientes procesos se caracteriza principalmente por la pérdida de conocimientos generales como conceptos o hechos históricos, así como por la anomia y los déficits en la comprensión de palabras aisladas?:', 'La encefalopatía postanóxica con lesión bilateral de la región CA1 del hipocampo.', 'La demencia semántica con lesiones típicas en el lóbulo temporal anterior.', 'El síndrome de Korkasoff con afectación de cuerpos mamilares y tálamo dorsomedial.', 'La enfermedad de Huntington con atrofia de los cuerpos estriados y demencia progresiva.', NULL, 'b', NULL, NULL),
  (2024, 65, NULL, 'En relación con los neurotransmisores del sistema nervioso central:', 'La toxina botulínica, la atropina y el veneno de la araña viuda negra, son sustancias antagonistas de la acetilcolina.', 'Las neuronas noradrenérgicas tienen sus cuerpos celulares en el locus coeruleus exclusivamente, sin presencia significativa en otras regiones.', 'La mayoría de los potenciales tras sinapsis serotoninérgicas tienen carácter inhibitorio, además de estar ampliamente distribuidos por el sistema nervioso central.', 'Los receptores dopaminérgicos, normalmente acoplados a proteínas G, son todos ionotrópicos.', NULL, 'c', NULL, NULL),
  (2024, 66, NULL, 'El modelo de covariación de Kelley (1967) de la atribución causal postula que las personas tratan de identificar el “por qué” del comportamiento de los demás, teniendo en cuenta tres factores fundamentales:', 'Internalidad-externalidad, estabilidad-inestabilidad y controlabilidad.', 'Capacidad, esfuerzo y dificultad de la tarea.', 'Distintividad, consenso y consistencia.', 'Intencionalidad, deseabilidad social y consecuencias.', NULL, 'c', NULL, NULL),
  (2024, 67, NULL, '¿Cómo se denomina la técnica de condescendencia que consiste en comenzar con una solicitud grande y después, cuando ésta es rechazada, rebajarla a una menor (la que realmente se deseaba desde el principio)?:', 'Técnica del pie en la puerta.', 'Técnica de la puerta en la cara.', 'Técnica del amago.', 'Técnica de “esto no es todo”.', NULL, 'b', NULL, NULL),
  (2024, 68, NULL, '¿Qué trató de explicar la teoría de la acción razonada de Ajzen y Fishbein (1980)?:', 'Cómo influyen las actitudes sobre el comportamiento.', 'Cómo la persuasión puede cambiar las actitudes.', 'Cómo los autoconceptos cambian con las situaciones.', 'Cómo la autoeficacia influye en la conducta prosocial.', NULL, 'a', NULL, NULL),
  (2024, 69, NULL, '¿A qué hace referencia la “holgazanería social” descrita por Latané, Williams y Harkins (1979)?:', 'A la tendencia a ejercer menor esfuerzo cuando se conjuntan los esfuerzos hacia una meta común que cuando la responsabilidad es individual.', 'A la tendencia a pensar que las demás personas del grupo no se esfuerzan lo suficiente, en comparación a lo que se esfuerza uno mismo.', 'A la tendencia a eludir las responsabilidades individuales cuando la figura de autoridad (por ejemplo, un jefe) no está presente.', 'A la tendencia a trabajar lo mínimo posible si no hay un refuerzo externo que motive el esfuerzo.', NULL, 'a', NULL, NULL),
  (2024, 70, NULL, '¿Qué teoría explica la tendencia de las personas a reducir el impacto de la amenaza al concepto de sí mismo concentrándose y afirmando su competencia en alguna otra área?:', 'Teoría de la autopercepción de Bem (1972).', 'Teoría de la autoafirmación de Steele (1988).', 'Teoría de la reactancia de Brehm (1966).', 'Teoría de la sobrejustificación de Deci y Ryan (1991).', NULL, 'b', NULL, NULL),
  (2024, 71, NULL, '¿Cómo conceptualizaron Latané y Darley (1970) el proceso de decisión de ayudar en una emergencia?:', 'En tres pasos: (1) interpretar la situación como emergencia; (2) observar lo que hacen las demás personas; (3) decidir qué se puede hacer.', 'En cuatro pasos: (1) prestar atención a la situación; (2) interpretar la situación como emergencia; (3) empatizar con la persona que necesita ayuda; (4) tomar la decisión de ayudar.', 'En cinco pasos: (1) prestar atención a la situación; (2) interpretar la situación como emergencia; (3) asumir la responsabilidad de ayudar; (4) decidir qué se puede hacer o cómo ayudar; (5) prestar ayuda.', 'En seis pasos: (1) prestar atención a la situación; (2) interpretar la situación como emergencia; (3) observar lo que hacen las demás personas; (4) empatizar con la persona que necesita ayuda; (5) asumir la responsabilidad de ayudar; (6) prestar ayuda.', NULL, 'c', NULL, NULL),
  (2024, 72, NULL, 'En el estudio de los prejuicios, ¿cómo se denomina a la tendencia consistente en considerar a los miembros de fuera del grupo (exogrupo) como todos iguales y a los miembros del grupo (endogrupo) como más diferenciados?:', 'Efecto de homogeneidad relativa.', 'Diferenciación del exogrupo.', 'Sesgo intragrupal.', 'Efecto de acentuación.', NULL, 'a', NULL, NULL),
  (2024, 73, NULL, 'La fuente principal de error de un coeficiente de fiabilidad calculado mediante formas alternativas de un test en aplicación diferida es:', 'El cambio en los contenidos de las formas más el muestreo de contenidos.', 'El muestreo de contenidos más el muestreo de tiempos.', 'El cambio en los calificadores más el muestreo de calificadores.', 'El muestreo de contenidos más la heterogeneidad de los ítems.', NULL, 'b', NULL, NULL),
  (2024, 74, NULL, '¿Qué índice hace referencia a la proporción de sujetos que realizan el test con los que se obtienen resultados correctos?:', 'Sensibilidad.', 'Eficacia.', 'Valor predictivo positivo.', 'Especificidad.', NULL, 'b', NULL, NULL),
  (2024, 75, NULL, 'Si en un contraste unilateral derecho utilizamos como nivel de significación 0,005:', 'La probabilidad de mantener H0 siendo falsa es 0,005.', 'La probabilidad de rechazar H0 siendo verdadera es 0,005.', 'La probabilidad de mantener H0 siendo falsa es 0,995.', 'La probabilidad de rechazar H0 siendo verdadera es 0,995.', NULL, 'b', NULL, NULL),
  (2024, 76, NULL, 'El hecho de que los dos factores principales que afectan a la potencia sean el tamaño del efecto y el tamaño de la muestra implica que:', 'El tamaño del efecto toma en cuenta la diferencia predicha entre medias (cuanto mayor es la diferencia, mayor es d) y la varianza muestral (cuanto mayor es la varianza muestral, mayor es d).', 'El tamaño del efecto influye en la potencia, ya que, a mayor tamaño del efecto, mayor es la superposición entre las distribuciones de medias de la población predicha y el área de rechazo de la distribución de medicas correspondiente a la población comparativa.', 'Con un determinado tamaño del efecto, los estudios con más potencia tienen intervalos de confianza más largos.', 'A mayor muestra, menor es la varianza de la distribución de medias, de forma tal que para un determinado tamaño del efecto existe menor superposición entre las distribuciones.', NULL, 'd', NULL, NULL),
  (2024, 77, NULL, 'Señale la respuesta FALSA:', 'La distribución normal es asintótica con respecto al eje de abscisas.', 'Hay toda una familia de curvas normales, dependiendo de los valores de la media y desviación típica. De entre ellas, la más importante es la que tiene media 100 y desviación típica 15, para la que Wechsler propuso el nombre de distribución normal unitaria.', 'Cualquier combinación lineal de variables aleatorias normales se ajusta también al modelo normal.', 'Los puntos de inflexión en una distribución normal se encuentran en los puntos correspondientes a la media más/menos una desviación típica.', NULL, 'b', NULL, NULL),
  (2024, 78, NULL, '¿Cuál es la nueva regla de medida que la teoría de la respuesta al ítem propone en contraposición a las reglas de la teoría clásica de los test?:', 'Pueden establecerse comparaciones en general entre formas diferentes de test, sin el requerimiento del paralelismo.', 'Formatos mixtos de ítems llevan a desequilibrios de ponderación de las puntuaciones totales.', 'Test largos son más fiables que test cortos.', 'En el análisis de las propiedades psicométricas se enfatiza el test como unidad de análisis.', NULL, 'a', NULL, NULL),
  (2024, 79, NULL, 'Siguiendo la taxonomía de Murdock (2016), adaptada por Wampold (2019), para ordenar el mosaico que es el campo de la psicoterapia y delinear los diferentes modelos disponibles en la actualidad, éstos deben cumplir con ciertas propiedades y características. ¿Qué modelo teórico se sustenta en una epistemología que proviene de la fenomenología?:', 'Modelo cognitivo-conductual.', 'Modelo psicodinámico.', 'Modelo humanista-existencial.', 'Modelo contextual.', NULL, 'c', NULL, NULL),
  (2024, 80, NULL, '¿En qué teoría relacionada con las fobias se sugiere que, desde el punto de vista del sujeto, existe una respuesta nociva “Gestaltlike”?:', 'Modelo de Watson y Rayner.', 'Teoría de incubación de la ansiedad de Eysenck.', 'Modelo bifactorial mediacional de Mowrer.', 'Teoría de preparación de Seligman.', NULL, 'b', NULL, NULL),
  (2024, 81, NULL, 'En relación con el trastorno de ansiedad social:', 'En los adultos mayores, la ansiedad social puede incluir la mejora de los síntomas de enfermedades médicas.', 'El inicio tardío predice la aparición posterior de cuadros depresivos y abuso de sustancias, lo cual, además, predice altos niveles de disfuncionalidad e interferencia en la vida de las personas.', 'Raramente ocurre de manera aislada.', 'Las expectativas sociales desempeñan un papel importante en la explicación de una mayor búsqueda de ayuda en pacientes de género femenino.', NULL, 'c', NULL, NULL),
  (2024, 82, NULL, 'Según el DSM-5, en el trastorno de depresión mayor:', 'La hipersomnia y la hiperfagia son más probables en personas mayores.', 'La persistencia de síntomas depresivos durante la remisión, aunque sean leves, es un factor que predice claramente la recurrencia.', 'La diferencia con un proceso de duelo radica en que la disforia en el duelo aumenta en intensidad, en días o semanas, en función de la expectativa de volver a ser feliz.', 'El factor de riesgo que se ha descrito de manera más sistemática son los antecedentes de intentos o amenazas de suicidio que, además, en la mayoría de los suicidios consumados se han precedido de intentos fallidos.', NULL, 'b', NULL, NULL),
  (2024, 83, NULL, 'Señale la respuesta correcta sobre la activación conductual como tratamiento psicológico para la depresión:', 'Las actividades que se programan son aquellas que el análisis funcional revele como significativas, con independencia de que puedan ser evitaciones.', 'La versión formalizada por Jacobson et al. (1996) recupera la Ley de igualación de Hernstein (1970) para insistir en la importancia del reforzamiento positivo que tendrían ciertas conductas de la persona deprimida.', 'Las actividades que se programan son actividades agradables (por ejemplo, ver amigos, salir a pasear, ir al cine, etc.).', 'Los estudios coste-beneficio la han revelado como la intervención más eficiente en un sistema público de salud, en particular si se compara con la terapia cognitiva.', NULL, 'd', NULL, NULL),
  (2024, 84, NULL, 'En relación con la terapia interpersonal para la depresión:', 'Es una terapia que enfatiza la influencia decisiva de las relaciones tempranas en los patrones interpersonales disfuncionales implicados en la depresión.', 'Es una terapia orientada desde el diagnóstico.', 'Es una terapia con más fundamento teórico que empírico.', 'Es una terapia estructurada por fases y objetivos que debería llevarse a cabo en 10 sesiones.', NULL, 'b', NULL, NULL),
  (2024, 85, NULL, 'Según Wampold (2011), ¿qué característica de las siguientes se asocia con los especialistas en psicología clínica más eficaces?:', 'Tienen una dilatada experiencia clínica.', 'Son conscientes de sus procesos psicológicos internos y no los “inyectan” en el proceso psicoterapéutico.', 'Han realizado un proceso de psicoterapia personal reglado.', 'Proporcionan una explicación técnica del problema basada en un modelo teórico contrastado.', NULL, 'b', NULL, NULL),
  (2024, 86, NULL, '¿Cuál de los siguientes factores es mejor predictor del resultado de un tratamiento psicológico?:', 'El diagnóstico.', 'La cronicidad del problema.', 'El tipo de población.', 'El nivel de angustia pretratamiento.', NULL, 'd', NULL, NULL),
  (2024, 87, NULL, '¿En cuál de los siguientes niveles de asimilación de los problemas que se trabajan en psicoterapia (Stiles, 2001) se encontraría una persona que enuncia claramente su problema, identifica y diferencia contenidos mentales opuestos, muestra un afecto negativo pero manejable, sin entrar en pánico?:', 'Aplicación/elaboración.', 'Comprensión/insight.', 'Declaración del problema/clarificación.', 'Integración/dominio.', NULL, 'c', NULL, NULL),
  (2024, 88, NULL, 'Rogers describió tres condiciones que, según él, serían condiciones necesarias y suficientes para que la psicoterapia fuera eficaz. Hoy en día, la evidencia disponible muestra que:', 'Ninguna de las tres condiciones correlaciona con los resultados de la psicoterapia.', 'La empatía y la consideración positiva muestran resultados prometedores, pero hace falta más investigación.', 'La autenticidad del terapeuta es un elemento probablemente eficaz.', 'La congruencia goza de mayor nivel de evidencia que la consideración positiva.', NULL, 'c', NULL, NULL),
  (2024, 89, NULL, '¿Cómo se denomina, en terapia familiar sistémica, a la técnica de la escuela estructural en la que el psicólogo clínico dirige a los miembros de la familia para que hablen o interactúen entre ellos con el objetivo de observar y modificar las pautas de interacción familiar?:', 'Acomodación.', 'Desequilibrio.', 'Enfoque.', 'Escenificación.', NULL, 'd', NULL, NULL),
  (2024, 90, NULL, '¿Cuál de las siguientes afirmaciones es correcta con respecto al concepto de juego familiar desarrollado por Selvini Palazzoli?:', 'Otorga un papel prioritario al análisis sincrónico de las relaciones familiares.', 'Utiliza técnicas estratégicas con un componente lúdico para la reorganización de los límites intrafamiliares.', 'Analiza elementos contextuales para describir a las familias, obviando las creencias, valores y estrategias individuales.', 'Una de sus bases teóricas es la metáfora del juego de Michel Crozier.', NULL, 'd', NULL, NULL),
  (2024, 91, NULL, 'En la aplicación de la entrevista motivacional, ¿cuándo es conveniente que el clínico utilice el reflejo?:', 'Cuando el discurso es muy abundante.', 'Cuando el discurso es muy escaso.', 'Cuando se escuche discurso de mantenimiento.', 'Cuando se escuche discurso de cambio.', NULL, 'd', NULL, NULL),
  (2024, 92, NULL, 'El modelo de Valeria Ugazio identifica una polaridad semántica predominante en las familias de pacientes con distintos trastornos. Señale la relación correcta:', 'Poder y trastornos de la conducta alimentaria.', 'Bondad y trastornos del estado de ánimo.', 'Justicia y trastornos obsesivos.', 'Seguridad y trastornos fóbicos.', NULL, 'a', NULL, NULL),
  (2024, 93, NULL, '¿Cuál de los siguientes enfoques es una propuesta de integración entre la teoría de los constructos personales de G. Kelly y la terapia sistémica?:', 'La rejilla de polaridades familiares de Emily Watt.', 'El modelo ecológico-constructivo de Gianfranco Cecchin.', 'El sistema de constructos familiares de Harry Procter.', 'La terapia transteórica familiar de Giuliana Prata.', NULL, 'c', NULL, NULL),
  (2024, 94, NULL, '¿Cuáles son las fases de la terapia cognitiva post-racionalista de Vittorio Guidano?:', 'Reconstrucción de la experiencia inmediata, reconstrucción del estilo afectivo y análisis evolutivo.', 'Evaluación del sistema constructivo, formulación funcional del sistema y desafío del sistema constructivo.', 'Evaluación diacrónica, moviola y reintegración sincrónica.', 'Análisis histórico, análisis del funcionamiento actual y proyección a futuro.', NULL, 'a', NULL, NULL),
  (2024, 95, NULL, '¿Cuál es el primer paso en la intervención que propone Michael Mahoney en la psicoterapia constructivista?:', 'La evaluación del mundo interno del paciente utilizando la rejilla de constructos personales.', 'El cambio de expectativas asociadas al sistema constructivo para facilitar la apertura al cambio.', 'La búsqueda de excepciones, potenciando la autoeficacia y desafiando el sistema constructivo.', 'La focalización y recuperación del equilibrio, adquiriendo cierto sentido de calma psicofísica.', NULL, 'd', NULL, NULL),
  (2024, 96, NULL, '¿Qué dos direcciones o niveles se analizan en la psicoterapia cognitivo-narrativa de Gonçalves?:', 'Intrapsíquico y vincular.', 'Sincrónico y Diacrónico.', 'Objetivo y Narrativo.', 'Constructivo y Deliberativo.', NULL, 'b', NULL, NULL),
  (2024, 97, NULL, 'Dentro del marco de la psicoterapia focalizada en la transferencia para el tratamiento de personas que padecen trastorno límite de la personalidad, ¿cuáles son los tres canales de comunicación que hay que vigilar y monitorizar durante la sesión?:', 'El grado de inestabilidad del paciente, el grado de impulso autodestructivo del paciente y el grado de idealización del paciente hacia el terapeuta.', 'El contenido verbal del discurso del paciente, la comunicación no verbal del paciente y la contratransferencia del terapeuta.', 'Las instancias psíquicas del paciente: Yo, Ello y Superyó.', 'El contenido verbal del discurso del paciente, la comunicación no verbal del paciente y la comunicación escrita elaborada entre sesiones por el paciente.', NULL, 'b', NULL, NULL),
  (2024, 98, NULL, 'Dentro de la terapia dialéctico-conductual, uno de los módulos de habilidades que se trabaja es el de atención plena o mindfulness. Señale la opción FALSA sobre este módulo:', 'Dentro de las “Habilidades Qué” se encuentra la habilidad “Observar”.', 'Dentro de las “Habilidades Cómo” se encuentra la habilidad “No juzgar”.', 'Dentro de las “Habilidades Qué” se encuentra la habilidad “Participar”.', 'Dentro de las “Habilidades Cómo” se encuentra la habilidad “Mente Sabia”.', NULL, 'd', NULL, NULL),
  (2024, 99, NULL, 'Señale la opción FALSA con respecto al tratamiento del trastorno dependiente de la personalidad:', 'Robert F. Bornstein considera que en la experiencia disfuncional del paciente dependiente convergen múltiples niveles: cognitivo, motivacional, afectivo y conductual.', 'Los autores Ovelhoser y Fine proponen un modelo dividido en 4 etapas: dirección activa, aumento de la autoestima, fomento de la autonomía y prevención de recaídas.', 'La terapia dialéctico-conductual ha desarrollado un abordaje grupal específico para este tipo de problemática conocido como terapia dialéctico-conductual radicalmente abierta.', 'La psicoterapia orientada a la clarificación, la terapia cognitivo-analítica y la terapia de aceptación y compromiso han mostrado cierta evidencia de eficacia en el tratamiento del trastorno dependiente de la personalidad.', NULL, 'c', NULL, NULL),
  (2024, 100, NULL, 'En relación con el proceso psicoterapéutico, los elementos de la relación terapéutica y los métodos de adaptación:', 'La metacomunicación es un tipo de autorrevelación.', 'Las autorrevelaciones son una estrategia considerada probablemente eficaz.', 'La relación real se considera importante, pero todavía carece de investigación.', 'El manejo de la contratrasferencia se considera importante, pero todavía carece de investigación.', NULL, 'a', NULL, NULL),
  (2024, 101, NULL, '¿En cuál de los siguientes casos podríamos encontrarnos con un fenómeno de privación del duelo?:', 'En una persona que ha optado por una interrupción voluntaria del embarazo.', 'En una persona que ha perdido a varios seres queridos en un mismo accidente.', 'En una persona anciana que ha perdido a amigos, familiares y está perdiendo su propia salud.', 'En una persona que se encuentra de viaje en el momento del fallecimiento de un familiar.', NULL, 'a', NULL, NULL),
  (2024, 102, NULL, 'Al cumplir los 50, el médico de atención primaria de María le ha propuesto hacerse una mamografía preventiva. María ha decidido hacérsela porque cree que podría tener riesgo por sus antecedentes oncológicos familiares, se siente vulnerable y, aunque le han dicho que es una prueba bastante dolorosa, entiende que los beneficios de prevenir una enfermedad grave superan los inconvenientes de las pruebas médicas. ¿Cuál de los siguientes modelos explicaría mejor la decisión de María?:', 'Modelo de la Motivación para la Protección.', 'Modelo de la Creencia sobre la Salud.', 'Modelo de la Conducta Planeada.', 'Teoría de la Acción Razonada.', NULL, 'b', NULL, NULL),
  (2024, 103, NULL, 'Según Safran y Muran (2005), cuando se deteriora la alianza terapéutica, entre un especialista en psicología clínica y su paciente, por falta de acuerdo en los objetivos, de colaboración o de un vínculo emocional adecuado, puede estar sucediendo:', 'Una ruptura en la alianza.', 'Un conflicto en la alianza.', 'Una falla en la capacidad metacognitiva del clínico.', 'Una falla en la capacidad metacognitiva del paciente.', NULL, 'a', NULL, NULL),
  (2024, 104, NULL, 'La psicoterapia psicodinámica cíclica de Paul Wacthel (1977, 1985, 1987) es un ejemplo de:', 'Integración teórica amplia.', 'Integración técnica pragmática.', 'Integración técnica de orientación.', 'Integración teórica híbrida.', NULL, 'd', NULL, NULL),
  (2024, 105, NULL, '¿Cuál de las siguientes terapias está diseñada específicamente para el abordaje de la psicosis y el clúster A de personalidad?:', 'Terapia metacognitiva (Wells).', 'Terapia metacognitiva interpersonal (Semerari).', 'Terapia de insight y reflexión metacognitiva (Lysaker).', 'Terapia de esquemas (Young).', NULL, 'c', NULL, NULL),
  (2024, 106, NULL, 'Cuando un especialista en psicología clínica intenta que un paciente se adapte a su método de tratamiento, en vez de adaptarse él a las características del paciente, podría estar incurriendo en una actitud conocida como:', 'Arrogancia metodológica.', 'Rigidez.', 'Lecho de Procusto.', 'Terapeuta-centrismo.', NULL, 'c', NULL, NULL),
  (2024, 107, NULL, 'Bohart y Tallman (2010) proponen dos tipos de evidencias para demostrar el protagonismo de los seres humanos a la hora de resolver sus problemas psicológicos. ¿Cuál de los siguientes tipos de evidencias es una de ellas?:', 'Las que demuestran que las personas no son capaces de enfrentarse a problemas psicológicos sin la ayuda de un especialista.', 'Las que demuestran que las personas, solo cuando son usuarias de una psicoterapia, son agentes activos implicados en el cambio.', 'Las que demuestran que los mecanismos responsables del cambio de las personas son comunes a todos los tratamientos efectivos.', 'Las que demuestran que las personas, cuando son usuarias de una psicoterapia, siguen siendo agentes activos altamente implicados en el cambio.', NULL, 'd', NULL, NULL),
  (2024, 108, NULL, 'En relación con el rol de los factores comunes en los tratamientos psicológicos:', 'Cuando se aborda el estudio de los mecanismos de cambio en psicoterapia, la norma es que existe consenso sobre ciertas evidencias empíricas.', 'La existencia de 500 tipos de tratamientos psicológicos, con sus propios procesos formativos, sistemas de acreditación y credenciales, es un factor clave que facilita el avance científico de la psicoterapia.', 'Mostrar que determinada psicoterapia funciona para abordar un trastorno mental específico no agota la gran cuestión sobre cómo se ha producido dicho efecto.', 'La mayoría de modelos suelen explicar la efectividad de la psicoterapia apelando a los factores comunes involucrados en el tipo de tratamiento empleado y en base a su planteamiento teórico.', NULL, 'c', NULL, NULL),
  (2024, 109, NULL, 'Según el Modelo de los límites de la regulación de la ingesta (Herman y Polivy, 1984), ¿cuál es el elemento clave que desencadena la desinhibición alimentaria en personas restrictivas?:', 'La desinhibición aparece en cuanto se salen de la dieta, como un efecto de violación de la abstinencia.', 'La creencia de haber traspasado el límite autoimpuesto, independientemente de que sea cierto o no.', 'La alteración emocional, pues estas personas utilizan la alimentación para enmascarar el estrés de otras áreas de su vida.', 'El intento de suprimir los pensamientos sobre alimentos, pues los hace aún más presentes y aumenta el craving.', NULL, 'b', NULL, NULL),
  (2024, 110, NULL, '¿Qué se puede afirmar sobre la anorexia nerviosa (AN)?:', 'Alrededor de un 50% de los pacientes con AN experimentan depresión mayor a lo largo de la vida.', 'Cuando existe comorbilidad con la depresión mayor, en la mayoría de los casos, la depresión se inicia el mismo año o el siguiente a recibir el diagnóstico de AN.', 'Suele concurrir con un elevado neuroticismo y un bajo interés por el reforzamiento social.', 'Un 15% de las familias de los pacientes con AN presenta al menos un miembro con un trastorno alimentario clínico o subclínico.', NULL, 'b', NULL, NULL),
  (2024, 111, NULL, '¿Qué puede afirmarse sobre la migración diagnóstica en los trastornos de la conducta alimentaria?:', 'Aproximadamente la mitad de los pacientes con bulimia nerviosa desarrolla posteriormente anorexia nerviosa.', 'El cambio de diagnóstico de una bulimia nerviosa inicial a una anorexia nerviosa se produce en una minoría de los casos.', 'El cambio de diagnóstico de una bulimia nerviosa inicial a una anorexia nerviosa se produce en un 20% de los casos.', 'La migración diagnóstica es un fenómeno inusual en los trastornos de la conducta alimentaria.', NULL, 'b', NULL, NULL),
  (2024, 112, NULL, 'Con respecto al trastorno por evitación y restricción de la ingesta de alimentos:', 'La evitación de los alimentos se realiza según ciertas características sensoriales como la apariencia, color, olor, etc.', 'Existe una alteración en la forma de experimentar el peso y la forma corporal.', 'No se asocia con una pérdida de peso o déficit nutricional significativo.', 'La evitación de alimentos se realiza según las propiedades calóricas de los mismos.', NULL, 'a', NULL, NULL),
  (2024, 113, NULL, 'Rachman (1971) propuso un conjunto de variables asociadas al aumento de la sensibilización a los pensamientos que podrían explicar la persistencia de las obsesiones en el trastorno obsesivo compulsivo. ¿Cuál de las siguientes variables NO está entre ellas?:', 'El estado de disforia en el que se producen las obsesiones.', 'La expresión inadecuada de las propias emociones.', 'La falta de control percibido sobre uno mismo y el entorno.', 'Vivir acontecimientos estresantes.', NULL, 'b', NULL, NULL),
  (2024, 114, NULL, '¿Qué factores determinan según Ong (2020) la elección entre la terapia de exposición con prevención de repuesta y la terapia de aceptación y compromiso para el tratamiento del trastorno obsesivo compulsivo?:', 'La destreza del terapeuta o las preferencias del paciente.', 'La eficacia de la exposición con prevención de respuesta sobre las compulsiones.', 'La eficacia de la terapia de aceptación y compromiso sobre objetivos no estrictamente sintomáticos.', 'La comorbilidad con otros cuadros clínicos (trastornos del estado de ánimo, trastorno de personalidad obsesivo-compulsivo).', NULL, 'a', NULL, NULL),
  (2024, 115, NULL, '¿Cuál de las siguientes propuestas psicoterapéuticas integra entre sus fundamentos teóricos la teoría del apego de Bowlby?:', 'La terapia interpersonal de Klerman y Weissman.', 'La terapia Morita de Okubo.', 'La terapia estratégica de la escuela interaccional MRI de Palo Alto.', 'La terapia estratégica de Haley.', NULL, 'a', NULL, NULL),
  (2024, 116, NULL, 'Según el DSM-5, en relación con el trastorno obsesivo compulsivo (TOC):', 'Casi el 25% de las mujeres tiene un inicio antes de la edad de 10 años.', 'Alrededor de un 30% de los individuos con TOC tiene un trastorno de tics.', 'Si un individuo tiene obsesiones típicas del TOC (no completitud, daño) que conllevan conductas de acumulación compulsiva (adquirir todos los objetos de un conjunto para alcanzar sentido de integridad, no desechar periódicos ya que podría prevenir un daño) se debería diagnosticar trastorno por acumulación en su lugar.', 'La tasa de TOC en los familiares de primer grado de los adultos con TOC es tres veces mayor que entre los familiares de primer grado de los que no tienen este trastorno.', NULL, 'b', NULL, NULL),
  (2024, 117, NULL, 'El síndrome de crisis suicida propuesto por Galynker:', 'Es un estado afectivo y motivacional característico de los supervivientes de suicidio.', 'Describe el estado que se asocia con la conducta suicida a medio y largo plazo (hasta dos años).', 'Incluye entre sus criterios diagnósticos la desesperanza y la sensación de vacío.', 'Es un estado mental presuicida basado en la desregulación cognitiva y afectiva.', NULL, 'd', NULL, NULL),
  (2024, 118, NULL, 'Clark (2020) resume los argumentos a favor de separar el trastorno obsesivo-compulsivo (TOC) de los trastornos de ansiedad. ¿Cuál de los siguientes argumentos es FALSO?:', 'Los trastornos incluidos en el espectro obsesivo-compulsivo comparten un mismo circuito neuronal caracterizado por una hipoactivación de la región frontoestriada, que contrasta con el circuito de los trastornos de ansiedad, en los que se produce una activación de la amígdala.', 'El TOC y el resto de los trastornos del grupo tienen una respuesta similar al tratamiento farmacológico, en especial a los ISRS.', 'Las personas con TOC tienen dificultades para inhibir o detener un comportamiento una vez iniciado y en otras ocasiones las tienen para no iniciarlo.', 'Los trastornos del espectro obsesivo-compulsivo comparten un síntoma nuclear: la compulsividad, que varía en un continuo en cuyo extremo opuesto se sitúa la impulsividad.', NULL, 'a', NULL, NULL),
  (2024, 119, NULL, '¿Cuál de los siguientes enunciados es FALSO en el tratamiento psicológico de las obsesiones sin conducta compulsiva manifiesta?:', 'Es frecuente que la primera sesión de exposición sea altamente eficaz.', 'Hay mayor variedad de compulsiones y estrategias de neutralización encubiertas (en comparación con las estrategias manifiestas), son más idiosincrásicas y se asocian a una peor respuesta al tratamiento.', 'El uso de una cinta de audio continua proporciona un medio práctico, eficaz, de entrenar al paciente en la exposición y en la prevención de la respuesta para los acontecimientos encubiertos.', 'El objetivo del tratamiento consiste en cambiar el conocimiento de las obsesiones, evitar la neutralización y permitir, así, que los pacientes se habitúen a los pensamientos obsesivos.', NULL, 'a', NULL, NULL),
  (2024, 120, NULL, 'Según la clasificación de Custer (1984), revisada por Lesieur (1991), la primera fase en el proceso de adicción al juego se caracteriza por:', 'Las ganancias.', 'Una gran desorganización vital y desatención de todo lo demás.', 'Buscar ayuda terapéutica.', 'Intentar “cazar las pérdidas”.', NULL, 'a', NULL, NULL),
  (2024, 121, NULL, 'Con respecto al tratamiento de un paciente con un trastorno adictivo y otro trastorno psicopatológico comórbido:', 'El tratamiento debe ser secuencial (primero un trastorno y luego el otro).', 'El tratamiento debe ser integrado, abordando la problemática de forma conjunta y simultánea.', 'La intervención más adecuada es en paralelo, atendiéndole en dos servicios especializados al mismo tiempo.', 'Se debe tratar primero el trastorno más grave.', NULL, 'b', NULL, NULL),
  (2024, 122, NULL, 'En el tratamiento de los problemas relacionados con el trauma y la disociación, el objetivo principal en la fase de estabilización es:', 'Lograr que la persona entienda que los hechos traumáticos ya han finalizado y que ahora forman parte de su historia personal.', 'El abordaje específico de las experiencias relacionales pasadas no resueltas y que derivaron en un estilo de apego desorganizado en la persona.', 'Crear unas condiciones de seguridad suficientes y entrenar habilidades para establecer una relación terapéutica que posibilite el trabajo posterior.', 'Integrar la personalidad y establecer una identidad lo más unificada posible acorde a los valores y proyecto vital de la persona.', NULL, 'c', NULL, NULL),
  (2024, 123, NULL, 'Según la CIE-11, si una persona presenta síntomas de intrusión y reexperimentación, hipervigilancia, conductas de evitación y, además, dificultades graves y persistentes en la regulación del afecto, creencias sobre uno mismo de verse derrotado o sin valor, así como sentimientos de vergüenza, culpa o fracaso y dificultades para mantener relaciones y sentirse cerca de los demás, es más probable que cumpla criterios para un diagnóstico de:', 'Trastorno de estrés postraumático complejo.', 'Trastorno de identidad disociativo.', 'Trastorno límite de la personalidad.', 'Trastorno de estrés agudo.', NULL, 'a', NULL, NULL),
  (2024, 124, NULL, 'Dentro de las recomendaciones para el tratamiento del trastorno de estrés postraumático:', 'Debe ser práctica rutinaria la provisión de una sesión única y breve (debriefing) centrada en el trauma.', 'Los tratamientos no centrados en el trauma deben ser los de primera elección.', 'Los tratamientos centrados en el trauma deben ofrecerse con independencia del tiempo transcurrido desde el acontecimiento traumático.', 'Los tratamientos farmacológicos deben usarse como primera elección.', NULL, 'c', NULL, NULL),
  (2024, 125, NULL, 'Cuando un paciente con psicosis señala que le están intentando asesinar porque todo “huele a gas”, puede estar experimentado:', 'Acoasmas.', 'Fantosmias.', 'Fotomas.', 'Síndrome de Cotard.', NULL, 'b', NULL, NULL),
  (2024, 126, NULL, 'Según la teoría de la representación dual de Brewin et al. (2003):', 'La información vinculada al sufrimiento de un suceso traumático se almacena en paralelo en la memoria verbalmente accesible y en la memoria temporalmente accesible.', 'La información vinculada al sufrimiento de un suceso traumático se almacena de forma secuencial en la memoria verbalmente accesible y en la memoria situacionalmente accesible.', 'Existen dos sistemas de memoria que actúan de forma secuencial: la memoria verbalmente accesible y la memoria temporalmente accesible.', 'Existen dos sistemas de memoria que actúan en paralelo: la memoria verbalmente accesible y la memoria situacionalmente accesible.', NULL, 'd', NULL, NULL),
  (2024, 127, NULL, 'Los movimientos involuntarios, continuos, lentos, sinuosos y sin objetivo, se denominan:', 'Corea.', 'Estereotipias.', 'Automatismos.', 'Atetosis.', NULL, 'd', NULL, NULL),
  (2024, 128, NULL, 'Según la propuesta de Otto Kernberg sobre la organización estructural de la personalidad, ¿cuál de las siguientes características NO es un elemento constitutivo de la organización borderline de la personalidad?:', 'Uso de la escisión como principal mecanismo de defensa.', 'Difusión de identidad.', 'Egocentrismo.', 'Juicio de realidad mantenido.', NULL, 'c', NULL, NULL),
  (2024, 129, NULL, 'Según Barlow et al. (2018), los constructos transdiagnósticos nucleares en los trastornos emocionales consisten en:', 'La atención focalizada en señales de amenaza, la percepción de incontrolabilidad e impredecibilidad, las tendencias a la acción y conductas impulsadas por sesgos cognitivos y la evitación experiencial.', 'La auto-preocupación neurótica, la percepción de incontrolabilidad e impredecibilidad, las tendencias a la acción y conductas impulsadas por la emoción y la evitación emocional.', 'La auto-percepción neurótica, la percepción de incontrolabilidad e impredecibilidad, las tendencias a la acción y conductas impulsadas por sesgos cognitivos y la supresión emocional.', 'La atención focalizada en señales de amenaza, la percepción de incontrolabilidad e impredecibilidad, las tendencias a la acción y conductas impulsadas por la emoción y la evitación emocional.', NULL, 'b', NULL, NULL),
  (2024, 130, NULL, '¿Cómo se denomina a la experiencia alucinatoria que consiste en verse a sí mismo como un doble reflejado en un cristal, a menudo con una consistencia gelatinosa y transparente, con el conocimiento de que la figura humana que se está viendo es uno mismo?:', 'Autotopagnosia.', 'Autoscopia.', 'Alucinaciones extracampinas.', 'Desrealización.', NULL, 'b', NULL, NULL),
  (2024, 131, NULL, 'El síndrome de Charles Bonnet, un trastorno alucinatorio que se da en ancianos con patología orgánica central o periférica, se caracteriza por presentar:', 'Alucinaciones liliputienses.', 'Micropsias.', 'Pareidolias.', 'Alucinaciones negativas.', NULL, 'a', NULL, NULL),
  (2024, 132, NULL, 'Las investigaciones acerca de la aplicación de los modelos cognitivos al estudio de las alucinaciones auditivas en forma de voces han demostrado que:', 'Las creencias sobre malevolencia producen menor perturbación emocional en la persona.', 'Las creencias no repercuten ni en el afecto ni en los patrones de afrontamiento ante las voces.', 'Las creencias sobre benevolencia mantienen una relación inversa con los niveles de malestar que experimenta la persona.', 'Las creencias de familiaridad con las voces producen menor compromiso y aceptación sobre las mismas.', NULL, 'c', NULL, NULL),
  (2024, 133, NULL, 'Una persona que se encuentra en la fase de apofanía de Klaus Conrad (1958) y que cree que su piel está infectada por insectos o parásitos presenta:', 'Una alucinación cinestésica.', 'Una alucinación cenestésica.', 'Una creencia disfuncional de contenido hipocondríaco.', 'Un delirio hipocondríaco.', NULL, 'd', NULL, NULL),
  (2024, 134, NULL, 'En relación con las características diferenciales entre la depresión bipolar y unipolar:', 'La duración de los episodios suele ser menor en la depresión bipolar.', 'La presencia de síntomas catatónicos es más frecuente en la depresión unipolar.', 'Las personas que sufren de depresiones unipolares suelen tener un mayor número de episodios a lo largo de su vida.', 'Es más frecuente encontrar síntomas psicóticos en casos de depresión unipolar.', NULL, 'a', NULL, NULL),
  (2024, 135, NULL, 'Dentro de las principales intervenciones psicológicas con apoyo empírico para el trastorno bipolar se encuentra el cuidado sistemático. ¿Qué tipo de intervenciones incluye?:', 'Terapia centrada en la familia.', 'Intervención psicológica intensiva, empleando terapia cognitivo-conductual, terapia interpersonal y de ritmos sociales, intervenciones familiares y farmacológicas.', 'Intervenciones psicoeducativas.', 'Gestión de casos, tratamiento asertivo comunitario y equipos de atención en crisis.', NULL, 'd', NULL, NULL),
  (2024, 136, NULL, 'Con respecto al riesgo de suicidio en el trastorno bipolar (TB):', 'El riesgo de suicidio es mayor en el TB tipo I.', 'El riesgo de suicidio es de 20 a 30 veces superior al de la población general.', 'La historia previa de intentos de suicidio y el porcentaje de días con depresión en el último año no se asocian con suicidios consumados.', 'Existen diferencias muy significativas entre las tasas de prevalencia del intento de suicidio entre TB tipo I y TB tipo II.', NULL, 'b', NULL, NULL),
  (2024, 137, NULL, '¿A qué hace referencia el proceso “evocar” en la entrevista motivacional?:', 'Es el proceso en el que el especialista en psicología clínica y el paciente establecen una conexión útil y una relación terapéutica.', 'Es el proceso en el que se evalúa el problema, se determina qué se está haciendo mal y se proponen alternativas de cambio.', 'Es el proceso que permite desarrollar y mantener una dirección específica en la conversación sobre el cambio.', 'Es el proceso que supone hacer explícitas las motivaciones del paciente para el cambio.', NULL, 'd', NULL, NULL),
  (2024, 138, NULL, 'Los tratamientos con apoyo empírico se enfrentan a una realidad asistencial que rara vez se ajusta a las condiciones experimentales de validación de tratamientos. Para paliar este problema, se ha propuesto el concepto de:', 'Práctica basada en la evidencia para mejorar la validez interna de los tratamientos psicológicos.', 'Práctica basada en la evidencia para mejorar la validez externa de los tratamientos psicológicos.', 'Evidencia basada en la práctica como un complemento a la práctica basada en la evidencia para cubrir la brecha entre investigación y práctica clínica.', 'Evidencia basada en la práctica como una alternativa a la práctica basada en la evidencia para cubrir la brecha entre investigación y práctica clínica.', NULL, 'c', NULL, NULL),
  (2024, 140, NULL, 'Cuando un paciente nos comunica que al ver sacudir las sábanas de una cama, siente que le están sacudiendo a él y, además, se siente como un ente abstracto y fusionado con el entorno, está experimentado:', 'Pérdida de atribución personal.', 'Disociación del afecto.', 'Confusión de los límites del yo.', 'Escisión de la unidad del yo.', NULL, 'c', NULL, NULL),
  (2024, 141, NULL, 'Según la clasificación de los delirios de Karl Jaspers (1913), en los delirios primarios:', 'Se puede delimitar claramente el origen de los mismos.', 'Surgen comprensiblemente como consecuencia de otros procesos psíquicos.', 'Aparecen como intentos de explicación de experiencias anómalas previas.', 'Resultan difíciles de comprender y explicar.', NULL, 'd', NULL, NULL),
  (2024, 142, NULL, '¿Cuáles son las características esenciales de la presión del habla?:', 'La velocidad y la cantidad de discurso.', 'La tangencialidad, la incoherencia y la pérdida de meta.', 'La ensalada de palabras y la ilogicidad.', 'El pensamiento divagatorio y la autorreferencialidad.', NULL, 'a', NULL, NULL),
  (2024, 143, NULL, '¿Cuál es la clave que diferencia la tangencialidad del descarrilamiento y de la pérdida de asociaciones según Andreasen?:', 'Las respuestas que proporciona el paciente ante preguntas que se le formulan, no a transiciones en el habla espontánea.', 'Las respuestas del paciente y su repercusión en las transiciones con el interlocutor.', 'La transición del habla ante respuestas sugeridas con premisas no compartidas.', 'La afectación de la función pragmática del lenguaje ante excesivos paréntesis del interlocutor.', NULL, 'a', NULL, NULL),
  (2024, 144, NULL, '¿Qué síndrome afásico se caracteriza por frecuentes parafasias fonémicas, comprensión normal o algo afectada, repetición muy deteriorada y anomia?:', 'Afasia de Broca.', 'Afasia anómica amnésica.', 'Afasia transcortical mixta.', 'Afasia de conducción.', NULL, 'd', NULL, NULL),
  (2024, 145, NULL, '¿Qué modalidad sensorial de alucinación es más frecuente en la epilepsia del lóbulo temporal?:', 'Auditiva.', 'Visual.', 'Táctil.', 'Olfativa.', NULL, 'd', NULL, NULL),
  (2024, 146, NULL, '¿Cuál de las siguientes situaciones o fenómenos hacen más probable la producción de memorias falsas según la propuesta de Brewin y Andrews (2017)?:', 'La inducción de recuerdos mediante hipnosis.', 'La creación de imágenes con detalles personales relevantes.', 'La presión grupal, cuando están implicados fenómenos de conformidad social.', 'La obediencia a la autoridad, en contextos en los que el individuo no tiene margen para escapar.', NULL, 'b', NULL, NULL),
  (2024, 147, NULL, '¿Cuál de las siguientes distorsiones de la memoria se produce siempre con material de naturaleza semántica?:', 'Déjà vu.', 'Jamais vu.', 'Criptoamnesia.', 'Pseudopresentimiento.', NULL, 'c', NULL, NULL),
  (2024, 148, NULL, '¿Qué tipo de distorsión de la memoria es la hipermnesia?:', 'Parapraxia del reconocimiento.', 'Paramnesia del reconocimiento.', 'Paramnesia del recuerdo.', 'Parapraxia del recuerdo.', NULL, 'd', NULL, NULL),
  (2024, 149, NULL, 'El estilo amplificador somatosensorial de Barsky (1992):', 'Describe las alteraciones atencionales y valorativas del trastorno dismórfico corporal.', 'Explica la hipervigilancia hacia sensaciones físicas intensas y frecuentes presentes en trastornos de síntomas somáticos.', 'Fue renovado por el constructo de amplificación de la amenaza somática de Köteles y Witthöft.', 'Está centrado en las alteraciones atencionales de diferentes cuadros clínicos, sin tener en cuenta variables cognitivas.', NULL, 'c', NULL, NULL),
  (2024, 150, NULL, 'Un paciente escucha hablar a su hermana y siente un golpe en el estómago, convencida de que su hermana le ha agredido a pesar de encontrarse en otra habitación. ¿Cómo se llama este tipo de fenómeno perceptivo?:', 'Alucinación refleja.', 'Alucinación sintética.', 'Pseudoalucinación.', 'Alucinación funcional.', NULL, 'a', NULL, NULL),
  (2024, 151, NULL, 'En relación con el uso de benzodiacepinas:', 'No está claramente establecido que produzca síntomas de abstinencia tras su retirada después de un periodo prolongado de consumo.', 'Su uso crónico no se relaciona con el desarrollo de deterioro cognitivo.', 'Su uso crónico no se relaciona con el riesgo de caídas.', 'No es recomendable usarlas más allá de un período breve de 2-4 semanas.', NULL, 'd', NULL, NULL),
  (2024, 152, NULL, '¿En cuál de los siguientes trastornos o cuadros clínicos es más frecuente la aparición de alucinaciones auditivas?:', 'Episodio maniaco.', 'Depresión mayor.', 'Alucinosis alcohólica.', 'Delirium.', NULL, 'c', NULL, NULL),
  (2024, 153, NULL, 'Según el modelo alternativo para los trastornos de personalidad del DSM-5, ¿en qué rasgo se ubica la faceta suspicacia?:', 'Psicoticismo.', 'Desinhibición.', 'Antagonismo.', 'Desapego.', NULL, 'd', NULL, NULL),
  (2024, 154, NULL, '¿Cuál de los siguientes factores potencia la desregulación en el trastorno límite de la personalidad según el modelo de cascadas emocionales (Selby y Joiner, 2009)?:', 'La persistencia de la desorganización del apego.', 'La desconfianza epistémica.', 'La rumiación sobre aspectos emocionales negativos.', 'Las diadas objetales relacionales rígidas.', NULL, 'c', NULL, NULL),
  (2024, 155, NULL, 'Según el DSM-5, señale el criterio diagnóstico FALSO con respecto al trastorno de la personalidad dependiente:', 'Siente una preocupación no realista por miedo a que lo abandonen y tenga que cuidar de sí mismo.', 'Necesita a los demás para asumir responsabilidades en la mayoría de los ámbitos importantes de su vida.', 'Esfuerzos desesperados por evitar que le abandonen, hasta el punto de hacer voluntariamente cosas que le desagradan.', 'Cuando termina una relación estrecha, busca con urgencia otra relación para que le cuiden y apoyen.', NULL, 'c', NULL, NULL),
  (2024, 156, NULL, 'Según el DSM-5, señale la afirmación FALSA con respecto al trastorno obsesivo-compulsivo y trastornos relacionados:', 'La tricotilomanía requiere especificar si existe introspección buena, o poca introspección, o ausencia de introspección y creencias delirantes.', 'En el diagnóstico de trastorno por acumulación se requiere especificar con adquisición excesiva, siendo la forma más frecuente de adquisición la compra excesiva, seguida por la adquisición de artículos gratuitos.', 'El trastorno depresivo mayor es el trastorno comórbido más común del trastorno dismórfico corporal (TDC), con un inicio por lo general posterior al TDC.', 'El trastorno de excoriación requiere necesariamente que se realicen intentos repetidos de disminuir o dejar de rascarse la piel.', NULL, 'a', NULL, NULL),
  (2024, 157, NULL, '¿Cuál de las siguientes afirmaciones es correcta sobre la prevención de la psicosis en individuos con estados mentales de alto riesgo (EMAR)?:', 'Las intervenciones psicofarmacológicas han demostrado ser más efectivas que las psicológicas para prevenir la transición a la psicosis.', 'No se ha podido establecer una recomendación sólida para una intervención específica para la prevención de la psicosis en individuos con EMAR.', 'La terapia cognitivo-conductual, cuando se presenta combinada con intervenciones familiares, es el tratamiento recomendado como la intervención estándar en la prevención de la psicosis en los EMAR.', 'Las intervenciones basadas en las necesidades han sido desaconsejadas debido a su limitada eficacia en la prevención de la psicosis.', NULL, 'b', NULL, NULL),
  (2024, 158, NULL, 'La terapia de mejora cognitiva (CET; Hogarty y Greenwald, 2006) para la esquizofrenia:', 'Tiene como uno de sus objetivos aumentar el insight y la conciencia de problema.', 'Se aplica en personas en la fase aguda y de estabilización de la enfermedad, cuando existen déficits cognitivos objetivables.', 'Es una terapia de tipo contextual.', 'Incluye entrenamiento en cognición social.', NULL, 'd', NULL, NULL),
  (2024, 159, NULL, '¿Qué elementos forman parte de la terapia de aceptación y compromiso para la psicosis?:', 'Crear distancia con respecto al lenguaje y desarrollar la voluntad.', 'Plantear la posibilidad de que el problema sea el control y reestructurar polaridades semánticas contradictorias de la clínica delirante.', 'Crear un estado de desesperanza creativa y buscar la sintonización empática con el afecto.', 'Ayudar a crear un sentido trascendental del yo y estructurar la terapia para que sea evocadora.', NULL, 'a', NULL, NULL),
  (2024, 160, NULL, 'En relación con la prevalencia del trastorno esquizoafectivo:', 'Se estima una prevalencia vital estimada del 0,3%, con una incidencia superior en mujeres.', 'Se estima una prevalencia vital similar a la de la esquizofrenia, con una incidencia ligeramente superior en hombres.', 'Se estima una prevalencia vital del 0,3%, con una incidencia superior en hombres.', 'Se estima una prevalencia vital del 1,6%, con una incidencia superior en mujeres.', NULL, 'a', NULL, NULL),
  (2024, 161, NULL, 'Señale la respuesta FALSA en relación con los estados mentales de alto riesgo de psicosis (EMAR):', 'Entre las personas con EMAR que desarrollaran un cuadro psicótico, predomina la transición hacia trastornos del espectro esquizofrénico en comparación con trastornos psicóticos afectivos.', 'El grupo de EMAR de síntomas psicóticos atenuados es el más frecuente en comparación con los otros grupos de riesgo.', 'El grupo de EMAR de síntomas psicóticos atenuados está asociado a un mayor riesgo de transición en comparación con los otros grupos de riesgo.', 'Los EMAR se caracterizan por ser grupos heterogéneos con una evolución no lineal.', NULL, 'c', NULL, NULL),
  (2024, 162, NULL, 'En relación con las intervenciones familiares psicoeducativas para la esquizofrenia:', 'Han mostrado eficacia en la reducción de la carga y la emoción expresada familiar, pero escasa eficacia a la hora de reducir la sintomatología y las hospitalizaciones de los pacientes.', 'Se recomienda utilizar modelos terapéuticos que no incluyan la consideración del papel etiológico que tienen la conducta y la comunicación familiar en el desarrollo de la esquizofrenia.', 'Los resultados muestran mayor eficacia cuando las intervenciones son estructuradas, conductuales y de breve duración.', 'Se recomiendan los abordajes unifamiliares por encima de los multifamiliares.', NULL, 'b', NULL, NULL),
  (2024, 163, NULL, 'En el tratamiento psicológico de la esquizofrenia se recomienda ajustar las intervenciones en función de las fases del trastorno, ¿en qué fase se priorizaría la reducción de la sobreestimulación ambiental?:', 'En la fase de estabilización.', 'En la fase prodrómica.', 'En la fase estable.', 'En la fase aguda.', NULL, 'd', NULL, NULL),
  (2024, 164, NULL, 'En relación con las terapias cognitivo conductuales aplicadas a los delirios, ¿cuál de estas afirmaciones es cierta?:', 'Se recomienda aplicar la fase de análisis verbal posteriormente a la de comprobación empírica.', 'Se puede aplicar la fase de comprobación empírica de las creencias de forma aislada, ya que se ha mostrado igual de eficaz que aplicada de forma combinada con el análisis verbal.', 'El análisis de la lógica interna del delirio se realiza en la fase de comprobación empírica.', 'En la fase de comprobación empírica es recomendable poner a prueba tanto la creencia delirante como la alternativa no delirante.', NULL, 'd', NULL, NULL),
  (2024, 165, NULL, '¿Cuál de las siguientes terapias para la psicosis incluye la estrategia de normalización racional y se centra en normalizar la experiencia psicótica con el fin de desestigmatizar los síntomas y dejarlos abiertos a argumentos racionales?:', 'La terapia de potenciación de las estrategias de afrontamiento de Tarrier.', 'La terapia metacognitiva interpersonal para la psicosis.', 'La terapia cognitiva de Chadwick, Birchwood y Tower.', 'La terapia cognitivo conductual de Kingdon y Turkingon.', NULL, 'd', NULL, NULL),
  (2024, 166, NULL, 'Señale la alternativa FALSA en relación con la terapia cognitiva basada en la persona para la psicosis perturbadora (PBCT):', 'El trabajo con esquemas pretende reducir el malestar asociado a los esquemas negativos sobre el yo y sobre los demás, y desarrollar esquemas positivos.', 'La PBCT, a diferencia de la terapia de aceptación y compromiso, busca como objetivo que el paciente se enfrente a los síntomas en lugar de cambiar la relación con las experiencias estresantes mediante aceptación y mindfulness.', 'Una de las dimensiones básicas de trabajo es el significado sintomático que incluye las experiencias psicóticas: delirios, voces y síntomas primarios.', 'Promueve un yo simbólico complejo, cambiante y emocionalmente variado.', NULL, 'b', NULL, NULL),
  (2024, 167, NULL, 'Según la propuesta de la selección sistemática de tratamientos de Beutler et al. (2000) y la psicoterapia prescriptiva (Beutler y Harwood, 2000):', 'El nivel de deterioro funcional no se relaciona necesariamente con el pronóstico del tratamiento.', 'El grado de apoyo social no es decisivo en la decisión de aplicar un tratamiento breve o más prolongado.', 'Las intervenciones mínimamente estructuradas son aconsejables para pacientes con afrontamiento centrado en la tarea.', 'El cambio en psicoterapia es más probable cuando el paciente se expone a los estímulos de evitación conductual y emocional.', NULL, 'd', NULL, NULL),
  (2024, 168, NULL, 'La terapia de enfoque modular para niños con ansiedad, depresión, trauma o problemas de conducta (Chorpita y Weisz, 2009):', 'Es un programa en formato grupal para niños y adolescentes entre 6 y 15 años.', 'Establece diagramas de flujo que secuencian las intervenciones que se aplican en un orden determinado, sin variaciones, tanto a los menores como a sus progenitores.', 'Incluye 33 módulos que se centran en los mecanismos transdiagnósticos de estas problemáticas desde un enfoque sistémico.', 'Utiliza módulos de tratamiento que se eligen en función de la gravedad y los problemas identificados en la entrevista previa con el menor y sus cuidadores.', NULL, 'd', NULL, NULL),
  (2024, 169, NULL, 'En relación con el tratamiento del trastorno negativista desafiante:', 'El manejo de conflictos y las habilidades de comunicación son las técnicas de tratamiento más habituales en los enfoques centrados en la familia.', 'La guía NICE recomienda intervenciones multimodales que incluyan a la familia para el tratamiento de niños entre 9 y 14 años.', 'En los tratamientos centrados en el niño y el adolescente, el entrenamiento en habilidades cognitivas se enfoca en entrenar habilidades de comunicación dirigidas tanto al niño como a la familia.', 'Los programas de tratamiento para padres presentan menor eficacia en la reducción del comportamiento disruptivo si se aplican en un entorno cultural diferente al utilizado en su diseño.', NULL, 'a', NULL, NULL),
  (2024, 170, NULL, 'Con respecto a la psicoterapia entre padres e hijos (Lieberman, 2004) para el tratamiento de niños o adolescentes expuestos a situaciones de violencia contra su cuidador principal:', 'Integra procedimientos del aprendizaje social, la terapia de aceptación y compromiso y la teoría del apego.', 'Las intervenciones se centran en promover la regulación emocional y afectiva, tanto del progenitor como del niño o el adolescente, y generar una narrativa conjunta del trauma.', 'Niño y progenitor son atendidos en sesiones individuales, programándose sesiones conjuntas cuando se requiera.', 'Las sesiones van orientadas a la identificación de pensamientos ansiosos, resolución de problemas y la exposición del niño o el adolescente a situaciones que le provoquen ansiedad.', NULL, 'b', NULL, NULL),
  (2024, 171, NULL, '¿Cuál de los siguientes aspectos es característico de los estados mentales de alto riesgo (EMAR)?:', 'Entre aquellas personas con EMAR que desarrollan un cuadro psicótico predomina la transición hacia psicosis afectivas en comparación con trastornos del espectro de la esquizofrenia.', 'Más de la mitad de las personas con EMAR presentan ideación suicida.', 'Algunas personas con EMAR no acaban desarrollando un trastorno psicótico franco, por lo que no requieren tratamiento.', 'El inicio temprano de medicación antipsicótica en personas con EMAR, especialmente durante la adolescencia, reduce el riesgo de psicosis.', NULL, 'b', NULL, NULL),
  (2024, 172, NULL, 'En relación con el trastorno de ansiedad por separación:', 'La edad de aparición más frecuente es a los 7 años, no pudiendo diagnosticarse a partir de esa edad. En niños más mayores, adolescentes y adultos, deben considerarse diagnósticos alternativos que cursen con sintomatología similar.', 'En los niños de 4-6 años, el diagnóstico comórbido más habitual es el de trastorno obsesivo-compulsivo.', 'En población clínica no parecen existir diferencias en cuanto a la distribución por sexo.', 'Un ejemplo de este trastorno sería el miedo a sufrir una crisis de pánico y que no exista nadie disponible para prestar ayuda, evitando por ello la separación.', NULL, 'c', NULL, NULL),
  (2024, 173, NULL, 'La terapia familiar funcional (Sexton et al., 2004) para niños y adolescentes con conductas adictivas:', 'Se aplica en cuatro fases distintas: compromiso, evaluación de la relación, cambio de comportamiento y generalización.', 'Entiende los problemas de conducta del adolescente como una forma de desviación del curso normal del desarrollo.', 'Se basa en el supuesto de que los comportamientos de cada miembro de la familia tienen una función positiva y negativa, incluyendo el comportamiento antisocial del adolescente.', 'Incorpora principios de modificación de conducta, terapia familiar estructural y estratégica.', NULL, 'c', NULL, NULL),
  (2024, 174, NULL, 'La terapia multidimensional del duelo (Hill et al., 2019):', 'Es una intervención psicosocial que pretende reducir la pena, los síntomas de depresión y de estrés postraumático, dar sentido a la pérdida y promover el desarrollo adaptativo de los niños y adolescentes.', 'Es un programa en formato grupal eficaz para reducir el estrés postraumático y los síntomas de dolor traumático.', 'Es una intervención familiar diseñada para promover la resiliencia en niños que han perdido a un progenitor, que se dirige explícitamente al trabajo con factores mediadores del proceso de duelo.', 'Es una intervención grupal que consta de actividades separadas para cuidadores y niños o adolescentes, que integra elementos psicoeducativos, narrativos y conductuales.', NULL, 'a', NULL, NULL),
  (2024, 175, NULL, 'En relación con el proceso de intervención psicológica con niños y adolescentes:', 'Los objetivos de tratamiento deben seleccionarse en función de la demanda y comportamientos problemáticos identificados por los padres.', 'En términos generales, a medida que aumenta la edad del paciente, la intervención con los padres debe ser más activa.', 'Algunos de los problemas consultados tienden a desaparecer o transformarse como resultado del propio desarrollo evolutivo, por lo que no requieren tratamiento.', 'Se recomienda atender preferentemente a los comportamientos no observables.', NULL, 'c', NULL, NULL),
  (2024, 176, NULL, '¿Cuál de los siguientes modelos de intervención es el más adecuado para tratar en el aula comportamientos que implican hetero-agresividad en un niño con diagnóstico de trastorno del espectro autista?:', 'Refuerzo.', 'Espera estructurada.', 'Intervención basada en familias.', 'Intervención basada en antecedentes.', NULL, 'd', NULL, NULL),
  (2024, 177, NULL, 'Señale la opción FALSA sobre el proceso psicoterapéutico con niños y adolescentes:', 'En general, los padres suelen aceptar más fácilmente las intervenciones que se centran en disminuir los comportamientos negativos que aquellas que se centran en aumentar los positivos.', 'El Inventario de Alianza de Trabajo no es apropiado para evaluar la alianza terapéutica en niños pequeños.', 'En general, los padres suelen aceptar más fácilmente las intervenciones que se centran en aumentar los comportamientos positivos que aquellas que se centran en disminuir los negativos.', 'Es importante evaluar las características individuales propias de los cuidadores.', NULL, 'a', NULL, NULL),
  (2024, 178, NULL, 'Según el DSM-5, el trastorno de movimientos estereotipados:', 'Comienza a partir de los dos años de edad.', 'Principalmente está formado por movimientos involuntarios, repetitivos y estereotipados con un aparente objetivo.', 'Puede incluir comportamientos autolesivos.', 'Incluye la tricotilomanía.', NULL, 'c', NULL, NULL),
  (2024, 179, NULL, 'La terapia de claves traumáticas es:', 'La adaptación a niños y adolescentes de la terapia de desensibilización y reprocesamiento por movimientos oculares.', 'Un abordaje psicodinámico del tratamiento del trauma en niños y adolescentes.', 'Una terapia cognitivo conductual diseñada para el tratamiento de los traumas tipo 1.', 'Una intervención que incluye la psicoeducación, la reestructuración cognitiva y la exposición a estímulos clave.', NULL, 'd', NULL, NULL),
  (2024, 180, NULL, 'Es posible diagnosticar un trastorno de la personalidad en la infancia y la adolescencia:', 'Sí, es posible diagnosticar un trastorno de la personalidad en preadolescentes, pero no en niños.', 'No, no es posible diagnosticar un trastorno de la personalidad antes de los 16 años.', 'Sí, es posible diagnosticar un trastorno de la personalidad en la infancia y la adolescencia sólo en casos excepcionales de extrema gravedad.', 'Sí, es posible en caso de que los rasgos desadaptativos sean generalizados, consistentes y presenten una duración de un año.', NULL, 'd', NULL, NULL),
  (2024, 181, NULL, '¿Cuál es una de las adaptaciones de la terapia dialéctico conductual para su aplicación a población adolescente?:', 'La no inclusión de habilidades de atención plena.', 'El entrenamiento específico en manejo de crisis de pánico.', 'La inclusión de un quinto módulo de habilidades denominado “Caminando por el sendero del medio”.', 'La exposición de la teoría biosocial a toda la familia.', NULL, 'c', NULL, NULL),
  (2024, 182, NULL, 'La adaptación de la terapia dialéctico conductual de Linehan a población adolescente fue desarrollada por:', 'Alec L. Miller y Jill H. Rathus.', 'Pamela A. Foelsch.', 'Patrick McGorry.', 'Sune Bo.', NULL, 'a', NULL, NULL),
  (2024, 183, NULL, 'Señale la respuesta FALSA en relación con los tratamientos psicológicos para la ansiedad en población infanto-juvenil:', 'Las terapias online basadas en terapia cognitivo-conductual han demostrado una eficacia similar a los tratamientos presenciales.', 'Los menores con ansiedad social pueden obtener mayor beneficio de las intervenciones individuales frente a las grupales.', 'Hay pocos estudios con rigor metodológico para tratar el mutismo selectivo.', 'Para la primera infancia se recomiendan los tratamientos de terapia familiar basados en terapia cognitivo-conductual.', NULL, 'b', NULL, NULL),
  (2024, 184, NULL, '¿Qué componentes debe incluir la terapia de inversión del hábito para los tics en la infancia y la adolescencia?:', 'Autorregistros, entrenamiento en respuesta competitiva y práctica lúdica.', 'Entrenamiento en respuesta competitiva, instigación y refuerzo positivo.', 'Entrenamiento en respuesta competitiva, práctica lúdica y refuerzo positivo.', 'Entrenamiento en conciencia, entrenamiento en respuesta competitiva y apoyo social.', NULL, 'd', NULL, NULL),
  (2024, 185, NULL, '¿Cuál de las siguientes intervenciones tiene como elemento terapéutico fundamental el modelado en vídeo?:', 'Terapia Morita.', 'Los años increíbles, “The Incredible Years”.', 'Cool Little Kids.', 'Terapia de interacción padres-hijos, PCIT.', NULL, 'b', NULL, NULL),
  (2024, 186, NULL, 'El modelo funcional de autolesiones de Nock y Prinstein (2004):', 'Propone diferentes intervenciones según el nivel de alteración del funcionamiento.', 'Incluye cuatro grandes grupos de funciones de las autolesiones.', 'Se centra en el análisis del riesgo de la conducta autolesiva.', 'Entiende la conducta autolesiva como una forma de afrontar la disociación.', NULL, 'b', NULL, NULL),
  (2024, 187, NULL, '¿Qué tratamiento de los trastornos de la conducta alimentaria en la infancia y la adolescencia incluye entre sus fases establecer una independencia saludable?:', 'Terapia cognitivo conductual mejorada.', 'Terapia sistémica estratégica.', 'Terapia basada en la familia.', 'Terapia interpersonal.', NULL, 'c', NULL, NULL),
  (2024, 188, NULL, 'En el ámbito del tratamiento de los trastornos mentales en la infancia y la adolescencia:', 'Aproximadamente el 60% de los jóvenes con problemas de salud mental no tienen acceso a psicoterapia.', 'En muchos trastornos mentales se impone la elección psicofarmacológica, conduciendo a la medicalización del problema y a los ampliamente conocidos efectos adversos.', 'Suele priorizarse la psicoterapia sobre la psicofarmacología por la ausencia de efectos adversos.', 'Se estima que aproximadamente un 25% de los niños y adolescentes presentan trastornos mentales susceptibles de mejorar con psicoterapia.', NULL, 'b', NULL, NULL),
  (2024, 189, NULL, 'En relación con el tratamiento “The Incredible Years”:', 'Es un tratamiento focalizado en el niño y el adolescente con trastorno desafiante-oposicionista.', 'Es un protocolo que se aplica de la misma forma con independencia de la edad del niño.', 'Entre sus objetivos se encuentra mejorar el rendimiento escolar.', 'Es un tratamiento dirigido a padres de niños con trastorno desafiante-oposicionista.', NULL, 'd', NULL, NULL),
  (2024, 190, NULL, 'Una niña de 8 años recibe el diagnóstico de depresión moderada en su Centro de Salud Mental Infanto-Juvenil. ¿Según la guía NICE (2019) cuál sería la mejor forma de proceder?:', 'Debería iniciarse tratamiento psicofarmacológico.', 'Debería iniciarse terapia cognitivo-conductual y si ésta no funciona en 4-6 sesiones suspenderse e iniciar tratamiento psicofarmacológico en monoterapia.', 'Debería iniciarse terapia cognitivo-conductual en combinación con psicofármacos.', 'Debería iniciarse terapia interpersonal basada en la familia.', NULL, 'd', NULL, NULL),
  (2024, 191, NULL, 'Una mujer consulta sobre cómo gestionar con sus hijos de 5 y 10 años los últimos días de vida y próximo fallecimiento del padre de los niños que padece un cáncer terminal. ¿Cuál de las siguientes ideas es recomendable transmitir?:', 'Se recomienda apartar a los niños de la realidad actual y no contarles nada sobre el trágico desenlace que está por venir para protegerlos.', 'Los niños pueden y deben percibir que los adultos están tristes, incluso cuando esa emoción les desborda.', 'El niño de 5 años no entiende el concepto de muerte por lo que se aconseja decirle, después del fallecimiento, que su padre “está durmiendo para siempre”.', 'Después del fallecimiento, se recomienda que los niños vuelvan al colegio cuanto antes.', NULL, 'd', NULL, NULL),
  (2024, 192, NULL, 'Con respecto a la evaluación de las fobias infantiles, señale la FALSA:', 'A partir de los cinco años se centra la evaluación en el niño.', 'Hay que tener en cuenta que los adultos tienden a subestimar la gravedad de las fobias infantiles.', 'Es relevante tener información sobre la reacción de los padres delante de la fobia.', 'Es importante conocer el repertorio de conductas de afrontamiento ante las situaciones temidas.', NULL, 'a', NULL, NULL),
  (2024, 193, NULL, 'El trastorno de desregulación disruptiva del estado de ánimo:', 'Es una categoría con validez y utilidad clínica probada.', 'Se añadió en el DSM-5 para evitar el sobrediagnóstico de TDAH en niños.', 'Es difícil de distinguir de problemas como la conducta desafiante.', 'Se caracteriza por la tristeza y la impulsividad.', NULL, 'c', NULL, NULL),
  (2024, 194, NULL, 'En relación con los trastornos de la eliminación:', 'En la valoración debemos estar atentos a las señales de posible abuso o maltrato infantil.', 'En la encopresis, si hay estreñimiento, suele ser suficiente con la intervención médica para el 60% de los casos.', 'El tratamiento psicológico para niños con enuresis con un trastorno del neurodesarrollo comórbido cuenta con el mismo grado de evidencia que para la enuresis sin dicha comorbilidad.', 'Existen pocos tratamientos empíricamente validados para la enuresis nocturna.', NULL, 'a', NULL, NULL),
  (2024, 195, NULL, 'La “Parent-Infant Psychoterapy” (PIP):', 'Es una intervención cuyo objetivo es disminuir las alteraciones de conducta en los niños.', 'Es una intervención que se recomienda para cualquier edad del niño.', 'Ayuda a la madre a reconocer las influencias de su propia vinculación con sus progenitores para relacionarlas con el ejercicio presente de su rol materno.', 'Es una intervención de orientación cognitivo-conductual.', NULL, 'c', NULL, NULL),
  (2024, 196, NULL, 'Según el DSM-5, ¿cuál de los siguientes trastornos mentales requiere del criterio alguedónico para su diagnóstico?:', 'Pica.', 'Trastorno del desarrollo intelectual.', 'Trastorno negativista desafiante.', 'Trastorno de la Tourette.', NULL, 'c', NULL, NULL),
  (2024, 197, NULL, 'En el trastorno de estrés postraumático en la infancia y la adolescencia:', 'Los síntomas de reexperimentación no son tan habituales como en los adultos.', 'Las manifestaciones conductuales y los comportamientos regresivos son habituales, sobre todo en los adolescentes.', 'Los sueños angustiosos siempre tienen que estar relacionados con la situación traumática.', 'En los niños mayores de 6 años se pueden producir juegos repetitivos en los que se expresen temas relacionados con el trauma.', NULL, 'd', NULL, NULL),
  (2024, 198, NULL, 'Una paciente de 10 años refiere textualmente en consulta de psicología clínica: “la pareja de mi madre, el otro día me obligó a ver una película porno y me tocó por debajo de la ropa”. En consecuencia:', 'Debemos contrastar esta información con la pareja de la madre y aclarar lo sucedido.', 'Debemos hacer preguntas para obtener el mayor número posible de detalles del relato de la paciente.', 'Debemos asegurar la protección de la paciente y denunciar esta situación lo antes posible.', 'Si el relato no es consistente, no debemos realizar ninguna actuación.', NULL, 'c', NULL, NULL),
  (2024, 199, NULL, '¿Cuál es la opción correcta para las tasas de prevalencia del trastorno de estrés postraumático en la infancia y la adolescencia?:', 'Son más elevadas para los sucesos interpersonales y especialmente en las niñas y las adolescentes.', 'Son más elevadas para los sucesos no interpersonales y con igual prevalencia en ambos géneros.', 'Son más elevadas para los sucesos no interpersonales y especialmente en las niñas y las adolescentes.', 'Son más elevadas para los sucesos interpersonales y con igual prevalencia en ambos géneros.', NULL, 'a', NULL, NULL),
  (2024, 200, NULL, '¿Cuál de los siguientes modelos de abordaje del trastorno del espectro autista propone una intervención centrada específicamente en la familia a través de un entrenamiento para padres?:', 'Método Hanen.', 'Modelo DIR (Developmental Individual Difference Relationship).', 'Método de entrenamiento en Respuestas Centrales (PRT).', 'Modelo Denver.', NULL, 'a', NULL, NULL),
  (2024, 201, NULL, '¿Qué afirmación es correcta con respecto al círculo arterial cerebral, también denominado polígono de Willis?:', 'Está formado por la anastomosis de las dos arterias vertebrales y las dos arterias carótidas internas.', 'Es una estructura de arterias que se encuentra específicamente en el cuerpo calloso.', 'Es una estructura vascular tan sumamente delicada que cualquier alteración en el tamaño de las arterias del círculo suele suponer la muerte del paciente.', 'Es la forma específica que toma la arteria basilar al llegar al cerebro para mantenerse aislada de otras arterias, como la arteria comunicante posterior y la arteria cerebral posterior.', NULL, 'a', NULL, NULL),
  (2024, 202, NULL, 'El objetivo de la prueba estadística no paramétrica de McNemar es:', 'Conocer diferencias o asociación entre variables en muestras pequeñas.', 'Conocer si existe relación entre dos o más variables.', 'Comparar si existen diferencias antes y después de un evento.', 'Comparar si existen diferencias entre tres o más grupos.', NULL, 'c', NULL, NULL),
  (2024, 203, NULL, 'Según el Modelo Cúbico de la Estructura del Intelecto de Guilford, ¿cuál de las siguientes dimensiones hace referencia al tipo de información que las personas procesan?:', 'Contenidos.', 'Operaciones mentales.', 'Productos.', 'Unidades.', NULL, 'a', NULL, NULL),
  (2024, 204, NULL, '¿Qué es el fórnix?:', 'Un haz de fibras que conecta diferentes regiones del cerebro.', 'El modo en que se denomina al complejo tálamo-hipotálamo.', 'Uno de los ganglios basales del cerebro.', 'Una fina lámina de sustancia gris separada del núcleo lenticular por la cápsula externa.', NULL, 'a', NULL, NULL),
  (2024, 205, NULL, 'De las siguientes pruebas de personalidad, ¿cuál es la que, construida desde un esquema teórico, presenta una mayor convergencia con la clasificación diagnóstica del DSM?:', 'MCMI-IV.', 'EPQ.', '16 PF.', 'BFQ, “Big Five”.', NULL, 'a', NULL, NULL),
  (2024, 206, NULL, '¿A qué se refiere el estado de identidad descrito por Marcia (1966, 1980) en el que una persona considera las alternativas en un momento de crisis y parece que se orienta a tomar un compromiso?:', 'Difusión de la identidad.', 'Exclusión.', 'Logro de la identidad.', 'Moratoria.', NULL, 'd', NULL, NULL),
  (2024, 207, NULL, '¿Cómo se denomina el trastorno en el que se produce una alteración de la atención y de la conciencia que se acompaña de un cambio en el funcionamiento de los procesos cognitivos, pudiéndose acompañar de alucinaciones de tipo visual y episodios de agitación?:', 'Trastorno de ideas delirantes.', 'Trastorno de despersonalizacióndesrealización.', 'Epilepsia del lóbulo temporal.', 'Delirium.', NULL, 'd', NULL, NULL),
  (2024, 208, NULL, '¿Cómo se denomina a la intensidad mínima en la que una persona puede detectar un estímulo el 50% de las veces que éste se presenta?:', 'Umbral diferencial.', 'Umbral relativo.', 'Umbral discriminativo.', 'Umbral absoluto.', NULL, 'd', NULL, NULL),
  (2024, 209, NULL, 'Un paciente tiene fobia a las arañas. Si con terapia conductual logra superar su miedo a las arañas dentro del despacho del especialista en psicología clínica, la conducta no se generalizará con la misma facilidad a nuevas situaciones. ¿Cómo puede solucionarse?:', 'Aumentando el efecto de contraste.', 'Reduciendo el efecto de renovación al hacer extinción en diferentes contextos.', 'Aumentando el tiempo de las sesiones de extinción.', 'No se puede reducir la renovación de la respuesta tras la extinción.', NULL, 'b', NULL, NULL),
  (2024, 210, NULL, '¿Cuáles son las tres etapas propuestas por la teoría de la disociación estructural para el tratamiento de niños con trauma grave?:', 'Creación de la alianza terapéutica y objetivos terapéuticos; entrenamiento en reducción de ansiedad; procesamiento de recuerdos traumáticos.', 'Psicoeducación; reelaboración narrativa del trauma (adaptado con dibujo o juego en función de la edad); reintegración en el entorno familiar y escolar.', 'Psicoeducación y objetivos; desarrollo de capacidades de afrontamiento (atención flexible, atención plena, imaginación); tratamiento de la disociación.', 'Estabilización, seguridad y reducción de síntomas; procesamiento de los recuerdos traumáticos; integración de estilos de afrontamiento adaptativos.', NULL, 'd', NULL, NULL);
