-- INSERT preguntas PIR 2024 (convocatoria FSE 2024, Psicología)
-- Fuente: Cuaderno_2024_P_0_C.pdf + Plantilla_Respuestas_FSE_v3.xlsx
-- Generado: 208 preguntas validas de 210 impresas (2 anuladas/en blanco excluidas: 5, 139)
-- especialidad/tema quedan NULL: se clasificaran en un paso posterior.

BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.preguntas WHERE "año" = 2024) THEN
    RAISE EXCEPTION 'Ya existen preguntas del año 2024 en la tabla preguntas — abortando para evitar duplicados.';
  END IF;
END $$;


COMMIT;

